/* === PostgreSQL 持久化层 ===
 * Render 免费版文件系统是临时的，服务重启后本地文件丢失。
 * 当设置了 DATABASE_URL 环境变量时，数据持久化到 PostgreSQL。
 * 未设置时，回退到本地文件存储（仅适合开发环境）。
 */
const DATABASE_URL = process.env.DATABASE_URL || '';
let pgPool = null;

const initDatabase = async () => {
  if (!DATABASE_URL) return false;
  try {
    pgPool = new pg.Pool({
      connectionString: DATABASE_URL,
      max: 5,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 5000,
      ssl: process.env.PG_SSL === 'false' ? false : { rejectUnauthorized: false }
    });
    await pgPool.query(`
      CREATE TABLE IF NOT EXISTS app_state (
        key VARCHAR(60) PRIMARY KEY,
        value JSONB NOT NULL,
        updated_at TIMESTAMPTZ DEFAULT NOW()
      )
    `);
    console.log('[DB] PostgreSQL \u6301\u4e45\u5316\u5df2\u542f\u7528');
    return true;
  } catch (err) {
    console.warn('[DB] PostgreSQL \u8fde\u63a5\u5931\u8d25\uff0c\u56de\u9000\u5230\u672c\u5730\u6587\u4ef6\uff1a', err.message);
    pgPool = null;
    return false;
  }
};

/* 内存存储回退（无 PostgreSQL 时使用） */
const appStateStore = new Map();

const dbGet = async (key) => {
  if (pgPool) {
    try {
      const res = await pgPool.query('SELECT value FROM app_state WHERE key = $1', [key]);
      return res.rows.length > 0 ? res.rows[0].value : null;
    } catch (err) {
      console.warn('[DB] \u8bfb\u53d6\u5931\u8d25 key=' + key + ':', err.message);
      return null;
    }
  }
  /* 无 PostgreSQL 时从内存 Map 读取 */
  const val = appStateStore.get(key);
  return val !== undefined ? val : null;
};

const dbSet = async (key, value) => {
  if (pgPool) {
    try {
      const serialized = JSON.stringify(value);
      await pgPool.query(
        'INSERT INTO app_state (key, value, updated_at) VALUES ($1, $2, NOW()) ON CONFLICT (key) DO UPDATE SET value = $2, updated_at = NOW()',
        [key, serialized]
      );
      return true;
    } catch (err) {
      console.error('[DB] 写入失败 key=' + key + ':', err.message);
      /* 重试一次 */
      try {
        await new Promise(r => setTimeout(r, 500));
        await pgPool.query(
          'INSERT INTO app_state (key, value, updated_at) VALUES ($1, $2, NOW()) ON CONFLICT (key) DO UPDATE SET value = $2, updated_at = NOW()',
          [key, JSON.stringify(value)]
        );
        console.log('[DB] 重试写入成功 key=' + key);
        return true;
      } catch (retryErr) {
        console.error('[DB] 重试写入也失败 key=' + key + ':', retryErr.message);
        return false;
      }
    }
  }
  /* 无 PostgreSQL 时写入内存 Map */
  appStateStore.set(key, value);
  /* 标记需要保存 */
  if (saveTimer) clearTimeout(saveTimer);
  saveTimer = setTimeout(saveDataNow, 2000);
};

