const completeChatText = async (messages, options = {}) => {
  return completeChatTextWithModel(messages, options, config.upstreamModel);
};

/* 带指定模型的完整响应函数 */
const completeChatTextWithModel = async (messages, options = {}, model) => {
  /* Fix6: 改为流式上游请求(stream:true)，逐块读取并拼接完整内容后返回 */
  const { timeoutMs = 120000, maxTokens = 8000, temperature } = options;
  const useModel = model || config.upstreamModel;
  if (!config.upstreamKey || config.upstreamKey.includes('请填写')) {
    const err = new Error('AI服务未配置。');
    err.code = 503; err.code2 = 5001;
    throw err;
  }
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  let resp;
  try {
    resp = await fetch(config.upstreamBase + '/chat/completions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: 'Bearer ' + config.upstreamKey },
      signal: controller.signal,
      body: JSON.stringify({
        model: useModel,
        stream: true,
        max_tokens: maxTokens,
        temperature: temperature != null ? temperature : 0.85,
        messages
      })
    });
  } catch (fetchErr) {
    clearTimeout(timer);
    if (fetchErr.name === 'AbortError') {
      const err = new Error('生成超时，请稍后重试。');
      err.code = 504; err.code2 = 5004;
      throw err;
    }
    const err = new Error('网络请求失败：' + (fetchErr.message || '未知错误'));
    err.code = 502; err.code2 = 5005;
    throw err;
  }
  clearTimeout(timer);
  if (!resp.ok) {
    let upstreamErrorMsg = '';
    try {
      const errBody = await resp.text();
      const errJson = JSON.parse(errBody || '{}');
      upstreamErrorMsg = errJson?.error?.message || errJson?.message || '';
    } catch {}
    if (resp.status === 429) {
      const err = new Error('AI服务繁忙，请稍后重试。');
      err.code = 429; err.code2 = 5007; err.isRateLimit = true;
      throw err;
    }
    const err = new Error(upstreamErrorMsg || ('上游API异常(' + resp.status + ')，请稍后重试。'));
    err.code = 502; err.code2 = 5006;
    throw err;
  }
  /* 流式读取：逐块拼接完整内容 */
  const upstreamContentType = resp.headers.get('content-type') || '';
  if (upstreamContentType.includes('text/event-stream') || upstreamContentType.includes('stream')) {
    const reader = resp.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let fullContent = '';
    const handlePayload = (payload) => {
      if (!payload || payload === '[DONE]') return;
      try {
        const json = JSON.parse(payload);
        if (json.error) {
          const errMsg = String(json.error.message || json.error.type || '');
          throw new Error('upstream_stream_error:' + errMsg);
        }
        const content = json.choices?.[0]?.delta?.content || json.choices?.[0]?.message?.content || '';
        if (content) fullContent += content;
        if (json.choices?.[0]?.finish_reason === 'length') {
          console.warn('[AI] Output truncated due to max_tokens limit. Consider increasing maxTokens.');
        }
      } catch (parseErr) {
        if (parseErr.message && parseErr.message.startsWith('upstream_')) throw parseErr;
      }
    };
    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const parts = buffer.split('\n\n');
      buffer = parts.pop() || '';
      for (const part of parts) {
        const dataLines = part.split('\n').filter((line) => line.startsWith('data:'));
        for (const line of dataLines) {
          handlePayload(line.replace(/^data:\s*/, '').trim());
        }
      }
    }
    buffer += decoder.decode();
    if (buffer.trim()) {
      const dataLines = buffer.split('\n').filter((line) => line.startsWith('data:'));
      for (const line of dataLines) {
        handlePayload(line.replace(/^data:\s*/, '').trim());
      }
    }
    if (!fullContent.trim()) {
      const err = new Error('AI返回空内容，请稍后重试。');
      err.code = 503; err.code2 = 5007;
      throw err;
    }
    return String(fullContent).trim();
  }
  /* 非流式回退：上游可能不支持流式，回退为JSON解析 */
  let bodyText = '';
  try { bodyText = await resp.text(); } catch {}
  let data = null;
  try { data = JSON.parse(bodyText || '{}'); } catch {
    const err = new Error('AI返回格式异常，请稍后重试。');
    err.code = 502; err.code2 = 5006;
    throw err;
  }
  const content = data.choices?.[0]?.message?.content || data.choices?.[0]?.delta?.content || '';
  return String(content || '').trim();
};

/* === 流式收集上游 AI 响应的辅助函数（含限流重试） ===
 * Gemini 等模型在非流式模式下生成长文本会卡住或超时，
 * 改用 stream:true 逐块读取，在服务端拼接完整内容后返回。
 * 自动检测 429 限流并重试最多 3 次。
 */
const streamComplete = async (prompt, options = {}) => {
  const { timeoutMs = 120000, maxTokens = 4000, retries = 3, model } = options;
  if (!config.upstreamKey || config.upstreamKey.includes('请填写')) {
    const err = new Error('AI服务未配置。');
    err.code = 503; err.code2 = 5001;
    throw err;
  }

  let lastError = null;
  for (let attempt = 0; attempt <= retries; attempt++) {
    if (attempt > 0) {
      // 重试前等待 3 秒
      await new Promise(r => setTimeout(r, 3000));
    }
    try {
      const result = await _streamCompleteOnce(prompt, { timeoutMs, maxTokens, model });
      if (result && result.length > 0) return result;
      // 空响应，可能是限流，重试
      lastError = new Error('AI返回空内容，可能服务繁忙，请稍后重试。');
      lastError.code = 503; lastError.code2 = 5007;
    } catch (e) {
      if (e.isRateLimit && attempt < retries) {
        console.warn('streamComplete 遇到限流，第' + (attempt + 1) + '次重试...');
        lastError = e;
        continue;
      }
      throw e;
    }
  }
  throw lastError || new Error('生成失败，请稍后重试。');
};

/* 带 fallback 的完整响应：主模型失败时尝试备用模型 */
/* 各功能专用模型：JSON生成/短文本用flash（快且不截断），深度推理用pro */
const FLASH_MODEL = '[次]gemini-3-flash-preview';
const SHOP_FOOD_FALLBACK_MODELS = ['[次-流抗截]gemini-3.1-pro-preview', '[次]gemini-2.5-pro', '[次]gemini-3-flash-preview'];
const streamCompleteWithFallback = async (prompt, options = {}) => {
  const { timeoutMs = 30000, maxTokens = 2500, temperature } = options;
  const primaryModel = config.upstreamModel;
  const modelsToTry = [primaryModel, ...SHOP_FOOD_FALLBACK_MODELS.filter(m => m !== primaryModel)];
  let lastError = null;
  for (let mi = 0; mi < modelsToTry.length; mi++) {
    const tryModel = modelsToTry[mi];
    try {
      console.log('[streamCompleteWithFallback] 尝试模型 ' + (mi + 1) + '/' + modelsToTry.length + ': ' + tryModel);
      const result = await completeChatTextWithModel([{ role: 'user', content: prompt }], { timeoutMs, maxTokens, temperature }, tryModel);
      if (result && result.length > 0) return result;
      lastError = new Error('AI返回空内容');
    } catch (e) {
      console.warn('[streamCompleteWithFallback] 模型 ' + tryModel + ' 失败: ' + e.message);
      lastError = e;
    }
  }
  throw lastError || new Error('所有模型均失败，请稍后重试。');
};

/* 单次上游请求：新上游模型流式不稳定，统一使用非流式请求 */
const _streamCompleteOnce = async (prompt, options) => {
  const { timeoutMs = 120000, maxTokens = 4000, temperature, model } = options;
  if (model) {
    return completeChatTextWithModel([{ role: 'user', content: prompt }], { timeoutMs, maxTokens, temperature }, model);
  }
  return completeChatText([{ role: 'user', content: prompt }], { timeoutMs, maxTokens, temperature });
};

/* === 带 system prompt 的完整响应辅助函数 === */
const streamCompleteWithSystem = async (sysPrompt, userMessage, options = {}) => {
  const { timeoutMs = 60000, maxTokens = 2000, temperature, model } = options;
  const messages = [
    { role: 'system', content: sysPrompt },
    { role: 'user', content: userMessage }
  ];
  if (model) {
    return completeChatTextWithModel(messages, { timeoutMs, maxTokens, temperature }, model);
  }
  return completeChatText(messages, { timeoutMs, maxTokens, temperature });
};

const extractJsonLikeField = (text, field) => {
  const source = String(text || '');
  const startRe = new RegExp('"' + field + '"\\s*:\\s*"');
  const startMatch = startRe.exec(source);
  if (!startMatch) return '';
  const start = startMatch.index + startMatch[0].length;
  const tail = source.slice(start);
  const nextMatch = tail.match(/"\s*,\s*"(?:title|authorName|excerpt|content|authorWords|tags)"\s*:/);
  let raw = nextMatch ? tail.slice(0, nextMatch.index) : tail;
  raw = raw.replace(/"\s*}\s*$/,'');
  return raw
    .replace(/\\n/g, '\n')
    .replace(/\\r/g, '\r')
    .replace(/\\t/g, '\t')
    .replace(/\\"/g, '"')
    .replace(/\\\\/g, '\\')
    .trim();
};




