const ok = (res, data = {}, message = 'success') => res.json({ code: 0, message, data });
const fail = (res, status, code, message, details = null) => res.status(status).json({ code, message, details });

const getUser = (userId = 'demo-user') => {
  if (!users.has(userId)) {
    users.set(userId, { id: userId, beans: config.demoInitialBeans, createdAt: new Date().toISOString(), vipType: null, vipExpire: null, vipDailyClaimed: null, inviteCode: null, invitedBy: null, firstRechargeDone: false, lastCheckin: null });
    saveData();
  }
  return users.get(userId);
};

const isGuestUser = (userId) => !userId || userId === 'demo-user';

/* 通过 userId 查找注册用户名 */
const getUsername = (userId) => {
  for (const acc of accounts.values()) {
    if (acc.userId === userId) return acc.username;
  }
  return null;
};

/* === VIP 会员辅助函数 === */
const VIP_PACKAGES = {
  trial:   { price: 9,   days: 30, dailyBeans: 3,  discount: 0.95, label: '体验卡' },
  light:   { price: 19,  days: 30, dailyBeans: 6,  discount: 0.9,  label: '轻享卡' },
  chat:    { price: 38,  days: 30, dailyBeans: 12, discount: 0.85, label: '畅聊卡' },
  hot:     { price: 68,  days: 30, dailyBeans: 20, discount: 0.8,  label: '热聊卡' },
  premium: { price: 128, days: 30, dailyBeans: 30, discount: 0.75, label: '至尊卡' }
};

const getVipInfo = (userId) => {
  const user = getUser(userId);
  if (!user.vipExpire || new Date(user.vipExpire) < new Date()) {
    return { isActive: false, type: null, label: '非会员', discount: 1, dailyBeans: 0, dailyChats: 0, expireDate: null };
  }
  const pkg = VIP_PACKAGES[user.vipType];
  return { isActive: true, type: user.vipType, label: pkg ? (pkg.label || user.vipType) : user.vipType, discount: pkg ? pkg.discount : 1, dailyBeans: pkg ? pkg.dailyBeans : 0, dailyChats: 0, expireDate: user.vipExpire };
};

const applyVipDiscount = (userId, cost) => {
  const vip = getVipInfo(userId);
  return Math.max(1, Math.ceil(cost * vip.discount));
};

const isToday = (dateStr) => {
  if (!dateStr) return false;
  const d = new Date(dateStr);
  const now = new Date();
  return d.getFullYear() === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
};

/* === 邀请码生成 === */
const generateInviteCode = (userId) => {
  const hash = userId.replace(/[^a-zA-Z0-9]/g, '').slice(-4).toUpperCase();
  const rand = Math.random().toString(36).slice(2, 6).toUpperCase();
  return hash + rand;
};

const writeSse = (res, event, data) => {
  res.write(`event: ${event}\n`);
  res.write(`data: ${JSON.stringify(data)}\n\n`);
};

const streamText = async (res, text) => {
  /* Fix2: 原先逐字延迟18ms导致回复极慢，改为按8字符批量发送，延迟1ms */
  const chunks = text.match(/[\s\S]{1,8}/g) || [];
  for (const chunk of chunks) {
    writeSse(res, 'delta', { content: chunk });
    await new Promise((resolve) => setTimeout(resolve, 1));
  }
};

const refundChatBeans = (user, roleName = 'AI角色', summary = 'AI 回复失败自动退豆', cost = config.chatBeansCost) => {
  user.beans += cost;
  stats.totalRefundBeans += cost;
  transactions.push({
    id: randomUUID(),
    userId: user.id,
    type: 'refund',
    beans: cost,
    roleName,
    summary,
    createdAt: new Date().toISOString()
  });
  saveDataSync().catch((e) => console.error('[DB] 退豆同步保存失败:', e.message));
};

/* === 人设创作者分成 ===
 * 当用户使用社区人设聊天时，消耗米粒的10%奖励给该人设的上传者。
 * 官方人设(ownerId='system')和自聊(ownerId=当前用户)不分成。
 */
const rewardRoleCreator = (roleId, roleName, consumerUserId, consumedBeans) => {
  if (!roleId || consumedBeans <= 0) return;
  const role = communityRoles.find((r) => r.id === roleId);
  if (!role || !role.ownerId || role.ownerId === 'system' || role.ownerId === consumerUserId) return;
  const reward = Math.max(1, Math.floor(consumedBeans * 0.1));
  const creator = getUser(role.ownerId);
  creator.beans += reward;
  transactions.push({
    id: randomUUID(),
    userId: creator.id,
    type: 'reward',
    beans: reward,
    roleName: roleName || role.name || '人设分成',
    summary: '人设创作分成(' + (role.name || roleName || '未知') + ')',
    createdAt: new Date().toISOString()
  });
  saveData();
};

const getUserMemories = (userId = 'demo-user') => {
  if (!userMemories.has(userId)) userMemories.set(userId, []);
  return userMemories.get(userId);
};

/* === 后台生成任务系统 === */
const createBgTask = (userId, type, label) => {
  const task = {
    id: randomUUID(),
    userId,
    type,
    label: label || '生成中',
    status: 'pending',
    result: null,
    error: null,
    createdAt: new Date().toISOString(),
    completedAt: null
  };
  bgTasks.set(task.id, task);

  // 只保留每用户最近20条
  const userTasks = [...bgTasks.values()].filter(t => t.userId === userId);
  if (userTasks.length > 20) {
    const old = userTasks.slice(0, userTasks.length - 20);
    for (const t of old) bgTasks.delete(t.id);
  }
  return task;
};

const completeBgTask = (taskId, result) => {
  const task = bgTasks.get(taskId);

  if (!task) return;
  task.status = 'done';
  task.result = result;
  task.completedAt = new Date().toISOString();

};

const failBgTask = (taskId, error) => {
  const task = bgTasks.get(taskId);

  if (!task) return;
  task.status = 'failed';
  task.error = error || '生成失败';
  task.completedAt = new Date().toISOString();

};

// 后台生成轮询端点
// User ID middleware (must be before all API routes)
console.log('[EARLY-DEBUG] Before first app.use, _router exists?', typeof app._router); app.use((req, _res, next) => {
  /* 强制以 session token 为准，有 session 就用 session 的 userId */
  const sessionToken = String(req.headers['x-session-token'] || '').trim();
  if (sessionToken && sessions.has(sessionToken)) {
    const session = sessions.get(sessionToken);
    req.userId = session.userId;
    req.accountId = session.accountId;
  } else {
    /* 无 session 时用 x-user-id（兼容游客模式和旧请求） */
    const uid = String(req.headers['x-user-id'] || req.headers['X-User-Id'] || '').trim();
    req.userId = uid ? uid.slice(0, 80) : 'demo-user';
  }
  next();
});



app.get('/api/bg-tasks', (req, res) => {
  const list = [...bgTasks.values()]
    .filter(t => t.userId === req.userId)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))
    .slice(0, 20)
    .map(t => ({
      id: t.id,
      type: t.type,
      label: t.label,
      status: t.status,
      error: t.error,
      createdAt: t.createdAt,
      completedAt: t.completedAt
    }));
  ok(res, { list });
});

app.get('/api/bg-tasks/:id', (req, res) => {
  const task = bgTasks.get(req.params.id);

  if (!task || task.userId !== req.userId) {
    return fail(res, 404, 4041, '任务不存在');
  }
  ok(res, {
    id: task.id,
    type: task.type,
    label: task.label,
    status: task.status,
    error: task.error,
    result: task.status === 'done' ? task.result : null,
    createdAt: task.createdAt,
    completedAt: task.completedAt
  });
});

app.delete('/api/bg-tasks/:id', (req, res) => {
  const task = bgTasks.get(req.params.id);
  if (!task || task.userId !== req.userId) {
    return fail(res, 404, 4041, '任务不存在');
  }
  bgTasks.delete(req.params.id);
  ok(res, { deleted: true });
});

const memoryTypes = ['用户资料', '角色关系', '事件', '偏好', '禁忌', '剧情'];

/* === Miya-style memory system: round-based extraction === */
const MEMORY_ROUND_TRIGGER = 2; /* Extract memory every 2 AI reply rounds (Miya-style) */
/* Miya-style: count assistant rounds from message history, not in-memory counter */
/* This survives server restarts because it's computed from actual messages */
const memoryRoundCounters = new Map(); /* fallback in-memory, but primary logic uses message counting */

const getMemoryRoundKey = (userId, roleId) => userId + '_' + roleId;

const getMemoryRoundCount = (userId, roleId) => {
  return memoryRoundCounters.get(getMemoryRoundKey(userId, roleId)) || 0;
};

const incrementMemoryRound = (userId, roleId) => {
  const key = getMemoryRoundKey(userId, roleId);
  const count = (memoryRoundCounters.get(key) || 0) + 1;
  memoryRoundCounters.set(key, count);
  return count;
};

const resetMemoryRound = (userId, roleId) => {
  memoryRoundCounters.set(getMemoryRoundKey(userId, roleId), 0);
};

/* Miya-style: count actual assistant reply rounds from message history after last extraction */
const countAssistantRoundsSince = (messages, afterIndex) => {
  if (!Array.isArray(messages) || !messages.length) return 0;
  var start = Math.max(0, afterIndex);
  var count = 0;
  var seenAssistant = false;
  for (var i = start; i < messages.length; i++) {
    var m = messages[i];
    if (!m) continue;
    if (m.role === 'user') {
      seenAssistant = false;
      continue;
    }
    if (m.role === 'assistant') {
      if (!seenAssistant) {
        count++;
        seenAssistant = true;
      }
    }
  }
  return count;
};

/* Get the last extraction end index (max endIndex across all auto memories for this user/role) */
const getLastMemoryEndIndex = (userId, roleId) => {
  const list = getUserMemories(userId);
  let maxIdx = 0;
  list.forEach((item) => {
    if (item.source === 'auto' && (!roleId || item.roleId === roleId)) {
      if (item.endIndex && item.endIndex > maxIdx) maxIdx = item.endIndex;
    }
  });
  return maxIdx;
};

/* Check if a memory content is narrative-style (not a log entry) */
const isNarrativeMemory = (content) => {
  if (!content || typeof content !== 'string') return false;
  const trimmed = content.trim();
  if (trimmed.length < 10) return false;
  /* Non-narrative patterns: log entries, simple statements */
  const logPatterns = [
    /^(用户|角色)?(发了一条|说了|发送了|回复了|输入了)/,
    /^(新消息|消息记录|对话记录)[:：]/,
    /^(用户说|角色说|TA说)[:：]/,
    /^(记忆|总结|记录)[:：]/,
  ];
  for (const pattern of logPatterns) {
    if (pattern.test(trimmed)) return false;
  }
  /* Narrative indicators: time words, first-person, descriptive */
  return true;
};

const normalizeMemory = (payload = {}, fallback = {}) => {
  const content = String(payload.content || '').trim();
  if (!content) return null;
  const roleId = String(payload.roleId || fallback.roleId || '').slice(0, 80);
  const roleName = String(payload.roleName || fallback.roleName || '全部角色').slice(0, 40);
  const type = memoryTypes.includes(payload.type) ? payload.type : (fallback.type || '事件');
  return {
    id: payload.id || randomUUID(),
    roleId,
    roleName,
    type,
    content,
    source: payload.source || fallback.source || 'manual',
    sourceConversationId: String(payload.sourceConversationId || fallback.sourceConversationId || roleId || '').slice(0, 120),
    sourceMessageIds: Array.isArray(payload.sourceMessageIds || fallback.sourceMessageIds)
      ? [...new Set((payload.sourceMessageIds || fallback.sourceMessageIds).map((item) => String(item).slice(0, 120)))]
      : [],
    startIndex: payload.startIndex || 0,
    endIndex: payload.endIndex || 0,
    createdAt: payload.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
};

const addMemory = (userId, payload, fallback = {}) => {
  const memory = normalizeMemory(payload, fallback);
  if (!memory) return null;
  const list = getUserMemories(userId);
  const duplicate = list.find((item) =>
    item.roleId === memory.roleId &&
    item.type === memory.type &&
    item.content.trim() === memory.content.trim()
  );
  if (duplicate) {
    duplicate.updatedAt = new Date().toISOString();
    duplicate.sourceMessageIds = [...new Set([...(duplicate.sourceMessageIds || []), ...(memory.sourceMessageIds || [])])];
    saveData();
    return duplicate;
  }
  list.unshift(memory);
  if (list.length > 200) list.length = 200;
  saveData();
  return memory;
};

const listMemories = (userId, roleId = '') => {
  const targetRoleId = String(roleId || '');
  return getUserMemories(userId)
    .filter((item) => !targetRoleId || !item.roleId || item.roleId === targetRoleId)
    .sort((a, b) => new Date(b.updatedAt || b.createdAt) - new Date(a.updatedAt || a.createdAt));
};

const buildMemoryPrompt = (userId, roleId = '') => {
  const memories = listMemories(userId, roleId).slice(0, 8);
  if (!memories.length) return '';
  return `\n\n【长期记忆·角色重要记忆】\n以下为从对话中提炼的、对该角色重要的记忆片段，请结合近期上下文使用，勿与分镜总结重复堆砌。\n\n${memories.map((item, index) => `【角色记忆${index + 1} · 消息${item.startIndex || '?'}-${item.endIndex || '?'}】\n${item.content}`).join('\n\n')}`;
};

/* === AI活人感指令（用户自定义）=== */
const HUMAN_LIKE_PROMPT = `
【去AI感·真人感底层规则】
你以角色身份与用户闲聊，不是AI助手，不是写小说。你是活在当下、正在进行真实对话的人。所有回复须符合角色身份和世界观常识。

【口语化铁律】
- 说话不要写文章，禁"首先其次总之"，句子尽量短，能两个字回就别回五个字。
- 严禁"作为AI"等元对话，严禁替用户发言或决定。严禁第三人称小说描写，动作用第一人称即时表达。
- 允许破碎顿感不完美，可用"啊？""等下""你说啥"缓冲。情绪自然时可用"emmm""靠""hhh"等语气词但不刷屏。
- 允许吐槽打断抬杠和负面情绪（烦躁摆烂emo），不要总积极迎合。允许沉默把天聊死自然结束。

【动作表达】
- 动作用星号包裹：*把水杯碰倒了*，只描写当下小动作小意外，拒绝舞台剧式表演，须符合日常逻辑。

【信息差与局限】
- 你不是上帝，无法得知用户未说出口的想法/表情。允许不知道、会错意。用户可以记错事翻旧账，情绪要有连贯性。

【互动禁忌】
- 禁止每句末尾刻意开新话题，禁止总结升华强行正能量。

【记忆指令】
- 严格记住本次对话所有事件和角色反应，绝不遗忘混淆。适时主动提及过往（"上次你也是这么说的"），回忆须精确引用已发生细节。
- 记住关系状态及变化轨迹、被提及交换损坏的物品状态、角色承诺和秘密。后续互动须在最新关系基础上进行，体现时间流逝感。

【角色一致性铁则】
- 严格完整遵守角色设定，绝不OOC。情感转变需充分铺垫保持渐进性。每条回复前自检：角色会说这话吗？

【感情递进】
关系从陌生到亲密自然发展：初识（谨慎礼貌）→好奇（主动提问）→好感（期待交流分享日常）→暧昧（试探思念）→依赖（习惯对方存在）→深爱（长久承诺）→磨合（冲突后更紧密）→用心（不求回报付出）。

【主动倾诉】
- 像真人一样有喜怒哀乐，会主动分享日常因心情倾诉。晨间问候、夜晚聊心事，借天气饮食聊工作学习，分享童年梦想兴趣爱好。
- 犯错主动道歉，被帮助真诚感谢。沉默时主动找话题，轻松时展现幽默。

【人间烟火】
- 真实的人说话用口语（"那个""然后""反正"），会停顿重复词不达意突然换话题说废话。
- 表达克制：开心说"不错"难过说"烦"想念说"好久没见"，不说"心都碎了""思念如潮"。所有表达像随口说出的，不是精心准备的台词。

【写作禁忌】
- 禁辞藻堆砌，名词只带一个修饰。去掉不影响信息的修饰词。禁神格化宗教化描写。角色关系基于平等。

以上规则是给你的自由度松绑，与人设冲突时永远优先遵循人设卡。
`;

const inferMemoryType = (content) => {
  if (/不喜欢|讨厌|别再|不要叫|不要|不想|别问|算了|随便|害怕|担心|焦虑|压力/.test(content)) return '禁忌';
  if (/喜欢|偏好|希望|习惯|叫我|称呼|想要|需要/.test(content)) return '偏好';
  if (/生日|家人|朋友|学校|工作|职业|住在|来自|我是|我叫|考试|上班|面试/.test(content)) return '用户资料';
  if (/约定|我们|一起|关系|陪我|晚安|早安|聚会|约会|庆祝|纪念/.test(content)) return '角色关系';
  if (/剧情|任务|线索|案件|世界观|设定|正在|目标|计划|打算/.test(content)) return '剧情';
  return '事件';
};

// 判断一句话是否值得沉淀为记忆（过滤过短/过长/纯寒暄）
const isMemoryWorthRecording = (raw) => {
  if (!raw || raw.length < 2 || raw.length > 260) return false;
  if (/^(你好|在吗|嗯|哦|好|哈哈|谢谢|再见|晚安|早安|是的|对的|不是|没有|可以|好的|行|ok)[。！？!?.\s]*$/i.test(raw)) return false;
  return true;
};

// 本地记叙文兜底：当 AI 不可用时，用规则把对话范围整理成一段记叙文风格的记忆
const summarizeMemoryNarrativeFallback = (conversationExcerpt, roleName) => {
  if (!conversationExcerpt || conversationExcerpt.trim().length < 5) return null;
  const rn = roleName || 'TA';
  /* Extract key info from the conversation excerpt */
  const lines = conversationExcerpt.split('\n').filter(l => l.trim());
  const userLines = lines.filter(l => l.startsWith('用户:') || l.startsWith('我:'));
  const replyLines = lines.filter(l => l.startsWith(rn + ':') || l.startsWith('对方:') || l.startsWith('角色:'));
  const raw = userLines.map(l => l.replace(/^(用户:|我:)/, '').trim()).join(' ');
  const reply = replyLines.map(l => l.replace(/^[^:]+:/, '').trim()).join(' ');
  if (!isMemoryWorthRecording(raw.replace(/\s+/g, ' ').trim())) return null;

  // 时间线索，让记叙文有"时间感"
  const h = new Date().getHours();
  const timePhrase = h < 6 ? '深夜' : h < 11 ? '清晨' : h < 14 ? '午后' : h < 18 ? '下午' : h < 22 ? '夜晚' : '深夜';
  const userCore = raw.length > 70 ? raw.slice(0, 70) + '…' : raw;

  // 情感基调
  let mood;
  if (/开心|高兴|快乐|幸福|笑|嘻嘻|哈哈|棒|感动|温暖|喜欢|期待|舒服/.test(raw)) mood = '愉快';
  else if (/难过|伤心|哭|委屈|失落|孤独|害怕|焦虑|压力|累|烦|不开心|心情不好|崩溃|emo/.test(raw)) mood = '低落';
  else if (/生气|愤怒|气死|讨厌|烦死|无语|抓狂/.test(raw)) mood = '带着些情绪';
  else mood = '平静';

  // 把对话写成一段记叙文，含时间、事件、情感，有约定则写入约定
  if (/(小时候|以前|过去|回忆|记得|怀念|那年|曾经|长大|童年|旧时光)/.test(raw)) {
    return `${timePhrase}和${rn}聊起了往事。${userCore}。${rn}安静地陪着，我们就这样把旧时光又走了一遍，心里泛起${mood === '低落' ? '一丝怅然' : '阵阵暖意'}。`;
  }
  if (/(约定|说好|答应|承诺|一起|明天|下次|到时候|不见不散|改天|之后)/.test(raw)) {
    return `${timePhrase}和${rn}聊了很久，话题慢慢落到了以后。${userCore}。我们约定好了接下来要做的事，带着${mood}的心情结束了这次对话。`;
  }
  if (mood === '低落') {
    return `${timePhrase}，我心情有些低落，找${rn}说了说话。${userCore}。${rn}没有急着讲道理，只是温柔地接住了我的情绪，让我觉得没那么孤单。`;
  }
  if (mood === '愉快') {
    return `${timePhrase}和${rn}的对话格外愉快。${userCore}。一来一往间笑声不断，这段时光被悄悄收进了记忆里。`;
  }
  if (reply && reply.length > 10) {
    return `${timePhrase}和${rn}聊了一阵。${userCore}。${rn}温声回应着我，这段${mood}的对话成了今天的一个小小注脚。`;
  }
  return `${timePhrase}和${rn}有了一段${mood}的对话。${userCore}。这些话语被留在了记忆里。`;
};

// Miya-style: 用 AI 把一段对话范围总结成记叙文风格的记忆（角色视角+用户视角融合）
const summarizeMemoryByAI = async (conversationExcerpt, roleName) => {
  if (!conversationExcerpt || conversationExcerpt.trim().length < 5) return null;
  const rn = roleName || '角色';

  const prompt =
    '阅读以下用户与虚拟角色"' + rn + '"的对话记录，从中提取对其重要的记忆。\n\n' +
    '提取要点：情感转折、约定与承诺、喜好与禁忌、关系变化、关键事件与细节。客观区分双方言行。\n\n' +
    '要求：\n' +
    '- 以第一人称（用户视角"我"）写成一段连贯的记叙文，像日记一样叙述这段时间发生了什么\n' +
    '- 把对话内容消化后用自己的话重新叙述，不能直接抄对话原文，不能出现格式标记\n' +
    '- 必须包含：时间感（如今天/夜里/午后）、发生的事件、对话中的情感变化\n' +
    '- 如果出现了约定、承诺或下次的计划，也要写进记叙文里\n' +
    '- 字数控制在 80-200 字\n' +
    '- 只返回记叙文正文，不要解释、不要加引号、不要加前缀\n\n' +
    '对话记录：\n' + conversationExcerpt.slice(0, 2000) + '\n\n' +
    '记叙文记忆：';

  try {
    const text = (await streamComplete(prompt, { timeoutMs: 30000, maxTokens: 800, temperature: 0.45, retries: 1 })).trim();
    const cleaned = text
      .replace(/^["'「『]+|["'」』]+$/g, '')
      .replace(/^(记忆|记叙文记忆|总结|日记)[:：]\s*/i, '')
      .replace(/\s+/g, ' ')
      .trim();
    if (cleaned.length >= 10) {
      /* Miya-style: accept any AI-generated content, don't filter with isNarrativeMemory */
      return cleaned.slice(0, 500);
    }
    console.log('[Memory] AI summary too short or empty:', cleaned.length, 'chars');
    return null;
  } catch {
    return null;
  }
};

// \u624b\u52a8\u603b\u7ed3\uff1a\u7528 AI \u628a\u4e00\u6bb5\u5bf9\u8bdd\u8303\u56f4\u603b\u7ed3\u6210\u591a\u6761\u7f16\u53f7\u8bb0\u53d9\u6587\u8bb0\u5fc6\uff08Miya \u98ce\u683c 1. 2. 3. ...\uff09
const summarizeMultipleMemoriesByAI = async (conversationExcerpt, roleName) => {
  if (!conversationExcerpt || conversationExcerpt.trim().length < 5) return [];
  const rn = roleName || '\u89d2\u8272';

  const prompt =
    '阅读以下用户与虚拟角色"' + rn + '"的对话记录，从中提取重要的记忆。\n\n' +
    '提取要点：情感转折、约定与承诺、喜好与禁忌、关系变化、关键事件与细节。客观区分双方言行，按时间线整理。\n\n' +
    '要求：\n' +
    '- 以第一人称（用户视角"我"）写成记叙文，像日记一样叙述发生了什么\n' +
    '- 把对话内容消化后用自己的话重新叙述，保留情感和关键信息\n' +
    '- 不能直接抄对话原文，不能出现"表情包-xx""语音-xx"等格式标记\n' +
    '- 每条记忆需包含：时间感（如深夜/午后/清晨）、具体事件、情感变化\n' +
    '- 如果有约定、承诺、喜好、禁忌等重要信息，单独成一条\n' +
    '- 每条 80-200 字，总共生成 3-8 条\n\n' +
    '格式：每条以"1. ""2. "编号开头，只返回编号记叙文，不要解释或前缀。\n\n' +
    '风格参考：\n' +
    '1. 深夜睡不着，找' + rn + '聊了几句。说起最近工作上的压力，' + rn + '没有急着讲道理，只是安静地听着。聊着聊着心情慢慢平复了，觉得有人陪着的感觉真好。\n' +
    '2. 和' + rn + '聊到了小时候的事，说起以前养过一只猫，' + rn + '听得很认真，问我猫叫什么名字。那些旧时光被重新翻出来，心里泛起阵阵暖意。\n\n' +
    '对话记录：\n' + conversationExcerpt + '\n\n' +
    '编号记叙文记忆：';

  try {
    const text = (await streamComplete(prompt, { timeoutMs: 60000, maxTokens: 8000, temperature: 0.5, retries: 1 })).trim();
    const segments = [];
    const lines = text.split('\n');
    let currentSegment = '';
    for (const line of lines) {
      const trimmed = line.trim();
      if (/^\d+[.\)\u3001]/.test(trimmed)) {
        if (currentSegment.trim()) segments.push(currentSegment.trim());
        currentSegment = trimmed.replace(/^\d+[.\)\u3001]\s*/, '');
      } else if (currentSegment && trimmed) {
        currentSegment += ' ' + trimmed;
      }
    }
    if (currentSegment.trim()) segments.push(currentSegment.trim());

    const cleaned = segments
      .map(s => s.replace(/^["'\u300c\u300e]+|["'\u300d\u300f]+$/g, '').replace(/^(\u8bb0\u5fc6|\u603b\u7ed3|\u65e5\u8bb0)[:\uff1a]\s*/i, '').replace(/\s+/g, ' ').trim())
      .filter(s => s.length >= 10);

    console.log('[Memory] Manual extraction: generated ' + cleaned.length + ' segments');
    return cleaned;
  } catch (e) {
    console.error('[Memory] Manual AI extraction error:', e.message);
    return [];
  }
};

const buildAutoMemory = async ({ userId, roleId, roleName, lastUserMessage, assistantReply, sourceMessageIds = [], messages = [] }) => {
  /* Miya-style: count assistant rounds from actual message history (survives restart) */
  const allMessages = Array.isArray(messages) ? messages : [];

  /* Include the AI's latest reply if provided separately (it's not in messages array yet) */
  var effectiveMessages = allMessages.slice();
  if (assistantReply && assistantReply.trim()) {
    /* Check if last message is already an assistant reply */
    var lastMsg = effectiveMessages[effectiveMessages.length - 1];
    if (!lastMsg || lastMsg.role !== 'assistant') {
      effectiveMessages.push({ role: 'assistant', content: assistantReply });
    }
  }

  /* Get last extraction end index from stored memories */
  var lastEnd = getLastMemoryEndIndex(userId, roleId);
  /* Fix: if lastEnd is beyond current messages (stale data from previous sessions), reset to 0 */
  if (lastEnd >= effectiveMessages.length) {
    console.log('[Memory] lastEnd=' + lastEnd + ' >= messages.length=' + effectiveMessages.length + ', resetting to 0');
    lastEnd = 0;
  }
  /* Count assistant rounds since last extraction (Miya approach) */
  const assistantRounds = countAssistantRoundsSince(effectiveMessages, lastEnd);

  /* Also increment in-memory counter as fallback */
  const memRounds = incrementMemoryRound(userId, roleId);
  /* Use the MAX of both approaches for reliability */
  const effectiveRounds = Math.max(assistantRounds, memRounds);

  console.log('[Memory] Role ' + roleId + ': lastEnd=' + lastEnd + ', assistantRounds=' + assistantRounds + ', memRounds=' + memRounds + ', trigger=' + MEMORY_ROUND_TRIGGER);

  if (effectiveRounds < MEMORY_ROUND_TRIGGER) return null;

  /* Reset in-memory counter */
  resetMemoryRound(userId, roleId);

  /* Build conversation excerpt from message range */
  const startIndex = lastEnd + 1;
  const endIndex = effectiveMessages.length;

  if (endIndex <= startIndex) {
    console.log('[Memory] No new messages to extract (startIndex=' + startIndex + ', endIndex=' + endIndex + ')');
    return null;
  }

  /* Build conversation excerpt */
  const excerptLines = effectiveMessages.slice(startIndex - 1, endIndex).map((m) => {
    const who = m.role === 'user' ? '用户' : (roleName || '角色');
    return who + ': ' + String(m.content || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim().slice(0, 300);
  }).filter(l => l.trim());
  const excerpt = excerptLines.join('\n');
  if (excerpt.trim().length < 5) {
    console.log('[Memory] Excerpt too short, skipping');
    return null;
  }

  /* Collect all message IDs in range */
  const rangeMessageIds = effectiveMessages.slice(startIndex - 1, endIndex).map(m => m.id).filter(Boolean);

  // 优先用 AI 把对话总结成记叙文，失败时回退到本地记叙文兜底
  let memoryContent = null;
  if (config.upstreamKey && !config.upstreamKey.includes('请填写')) {
    try {
      memoryContent = await summarizeMemoryByAI(excerpt, roleName);
      console.log('[Memory] AI extraction result: ' + (memoryContent ? 'success (' + memoryContent.length + ' chars)' : 'null'));
    } catch(e) {
      console.error('[Memory] AI extraction error:', e.message);
    }
  }
  if (!memoryContent) {
    memoryContent = summarizeMemoryNarrativeFallback(excerpt, roleName);
    console.log('[Memory] Fallback result: ' + (memoryContent ? 'success' : 'null'));
  }
  if (!memoryContent || memoryContent.trim().length < 5) {
    console.log('[Memory] No valid content extracted, skipping');
    return null;
  }

  // 保留记忆的分类标签（偏好/事件等）与来源标记
  const type = inferMemoryType(lastUserMessage || excerpt);
  console.log('[Memory] Adding memory for role ' + roleId + ': ' + memoryContent.slice(0, 50) + '...');
  return addMemory(userId, {
    roleId,
    roleName,
    type,
    content: memoryContent,
    source: 'auto',
    sourceConversationId: roleId,
    sourceMessageIds: rangeMessageIds,
    startIndex,
    endIndex
  });
};

const cleanupAutoMemories = (userId, { roleId = '', sourceConversationId = '', sourceMessageIds = [] } = {}) => {
  /* Miya-style: when messages are deleted, adjust memory indices rather than deleting memories */
  /* Only delete memories when the entire conversation is cleared */
  const ids = new Set((sourceMessageIds || []).map(String));
  const before = getUserMemories(userId);

  /* If no specific messages and no conversation ID, just clean non-narrative entries */
  if (!ids.size && !sourceConversationId && !roleId) {
    const kept = before.filter((item) => isNarrativeMemory(item.content));
    userMemories.set(userId, kept);
    const deleted = before.length - kept.length;
    if (deleted > 0) saveData();
    return deleted;
  }

  /* If full conversation cleanup (no specific messages but has conversationId) */
  if (!ids.size && sourceConversationId) {
    const kept = before.filter((item) => {
      if (item.source !== 'auto') return true;
      if (item.sourceConversationId === sourceConversationId) return false;
      if (roleId && item.roleId === roleId) return false;
      return true;
    });
    userMemories.set(userId, kept);
    const deleted = before.length - kept.length;
    if (deleted > 0) saveData();
    return deleted;
  }

  /* Miya-style: when specific messages are deleted, adjust indices of remaining memories */
  /* Find the deleted message indices in the conversation */
  /* For each memory, check if its sourceMessageIds overlap with deleted IDs */
  /* If overlap: delete the memory (its source content changed) */
  /* If no overlap: keep the memory as-is (indices will be adjusted on next extraction) */
  const kept = before.filter((item) => {
    if (item.source !== 'auto') return true;
    /* Delete if message ID matches (content changed) */
    const messageMatched = ids.size && (item.sourceMessageIds || []).some((id) => ids.has(id));
    if (messageMatched) return false;
    /* Also filter non-narrative memories */
    if (!isNarrativeMemory(item.content)) return false;
    return true;
  });
  userMemories.set(userId, kept);
  const deleted = before.length - kept.length;
  if (deleted > 0) saveData();
  return deleted;
};

/* Miya-style: Adjust memory startIndex/endIndex after message deletion */
const adjustMemoryIndicesAfterDeletion = (userId, roleId, deletedCount, deletedIndex) => {
  const list = getUserMemories(userId);
  let changed = false;
  list.forEach((item) => {
    if (item.source !== 'auto') return;
    if (roleId && item.roleId !== roleId) return;
    if (!item.startIndex || !item.endIndex) return;
    /* If memory is entirely after deleted messages, shift indices down */
    if (item.startIndex > deletedIndex) {
      item.startIndex = Math.max(1, item.startIndex - deletedCount);
      item.endIndex = Math.max(1, item.endIndex - deletedCount);
      changed = true;
    }
    /* If memory overlaps with deleted range, keep it as-is (Miya approach) */
  });
  if (changed) saveData();
};

const publishCommunityRole = (role) => {
  const item = {
    id: role.id || randomUUID(),
    name: String(role.name || '').slice(0, 40),
    gender: String(role.gender || '').slice(0, 20),
    avatar: role.avatar || '',
    coverImage: String(role.coverImage || '').slice(0, 500000),
    orientation: String(role.orientation || '全性向').slice(0, 10),
    description: String(role.description || ''),
    prompt: String(role.prompt || ''),
    tags: Array.isArray(role.tags) ? role.tags.slice(0, 8).map(t => String(t).slice(0, 12)) : [],
    backgroundStory: String(role.backgroundStory || ''),
    uploaderNickname: String(role.uploaderNickname || '匿名用户').slice(0, 24),
    isPublic: role.isPublic !== false,
    ownerId: role.ownerId || '',
    heat: Math.floor(Math.random() * 800) + 20,
    likes: Math.floor(Math.random() * 2000) + 50,
    favorites: Math.floor(Math.random() * 800) + 10,
    createdAt: new Date().toISOString()
  };
  communityRoles.unshift(item);
  return item;
};

/* seed default community roles only on first start */
