/* === 注册登录 API === */
app.post('/api/auth/send-code', async (req, res) => {
  const email = String(req.body?.email || '').trim().toLowerCase();
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
    return fail(res, 400, 5006, '请输入有效的邮箱地址。');
  }
  if (!emailReady) {
    return fail(res, 503, 5007, '邮件服务未配置，请联系管理员设置 BREVO_API_KEY。');
  }
  /* 检查邮箱是否已注册 */
  for (const acc of accounts.values()) {
    if (acc.email && acc.email === email) {
      return fail(res, 409, 5008, '该邮箱已注册，请直接登录。');
    }
  }
  /* IP 频率限制：同一 IP 每小时最多发 5 次验证码 */
  const ip = String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || 'unknown').split(',')[0].trim();
  const ipKey = 'code_' + ip;
  const ipRec = emailCodes.get(ipKey);
  const now = Date.now();
  if (ipRec && ipRec.count >= 5 && (now - ipRec.firstSent) < 3600000) {
    return fail(res, 429, 5009, '请求过于频繁，请 1 小时后再试。');
  }

  /* 生成 6 位验证码 */
  const code = String(Math.floor(100000 + Math.random() * 900000));
  emailCodes.set(email, { code, expires: now + 600000, sentAt: now });

  /* 更新 IP 计数 */
  if (!ipRec || (now - ipRec.firstSent) >= 3600000) {
    emailCodes.set(ipKey, { count: 1, firstSent: now });
  } else {
    ipRec.count++;
  }

  try {
    console.log('[Email] 准备发送验证码到:', email);
    await sendVerificationEmail(email, code);
    console.log('[Email] 验证码发送成功:', email);
    ok(res, {}, '验证码已发送至 ' + email + '，请查收邮件（注意检查垃圾邮件夹）。');
  } catch (e) {
    console.error('[Email] Send failed:', e.message, e.code || '');
    let errMsg = e.message || '邮件服务异常';
    /* 友好化常见错误 */
    if (errMsg.includes('EAUTH') || errMsg.includes('Invalid login')) {
      errMsg = '邮箱授权码错误，请检查 EMAIL_PASS 是否为 QQ邮箱的 SMTP 授权码（非QQ密码）';
    } else if (errMsg.includes('ECONNECTION') || errMsg.includes('connect')) {
      errMsg = '无法连接邮件服务器，可能是网络问题';
    } else if (errMsg.includes('EENVELOPE')) {
      errMsg = '收件地址被拒绝，请检查邮箱地址是否正确';
    }
    fail(res, 502, 5010, '验证码发送失败：' + errMsg + '。请联系管理员。');
  }
});

app.post('/api/auth/register', (req, res) => {
  const username = String(req.body?.username || '').trim();
  const password = String(req.body?.password || '');
  const inviteCode = String(req.body?.inviteCode || '').trim();
  const email = String(req.body?.email || '').trim().toLowerCase();
  const emailCode = String(req.body?.emailCode || '').trim();
  if (!username || username.length < 2) return fail(res, 400, 5001, '用户名至少2个字符。');
  if (!password || password.length < 4) return fail(res, 400, 5002, '密码至少4个字符。');
  if (!email || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return fail(res, 400, 5011, '请输入有效的邮箱地址。');
  if (!emailCode) return fail(res, 400, 5012, '请输入邮箱验证码。');
  /* 验证码校验 */
  const stored = emailCodes.get(email);
  if (!stored) return fail(res, 400, 5013, '请先发送验证码。');
  if (Date.now() > stored.expires) {
    emailCodes.delete(email);
    return fail(res, 400, 5014, '验证码已过期，请重新发送。');
  }
  if (stored.code !== emailCode) return fail(res, 400, 5015, '验证码不正确。');
  /* 检查用户名和邮箱是否已存在 */
  for (const acc of accounts.values()) {
    if (acc.username === username) return fail(res, 409, 5003, '用户名已存在。');
    if (acc.email && acc.email === email) return fail(res, 409, 5016, '该邮箱已注册。');
  }
  /* IP 注册限制：同一 IP 每天最多注册 3 个账号 */
  const ip = String(req.headers['x-forwarded-for'] || req.socket?.remoteAddress || 'unknown').split(',')[0].trim();
  const todayKey = 'reg_' + ip + '_' + new Date().toDateString();
  const todayCount = ipRegLimit.get(todayKey) || 0;
  if (todayCount >= 3) return fail(res, 429, 5017, '今日注册数量已达上限，请明天再试。');
  /* 验证通过，清除验证码 */
  emailCodes.delete(email);
  ipRegLimit.set(todayKey, todayCount + 1);

  const accountId = randomUUID();
  const userId = 'user_' + Date.now() + '_' + Math.random().toString(36).slice(2, 8);
  const account = { id: accountId, username, password, email, userId, createdAt: new Date().toISOString() };
  accounts.set(accountId, account);
  const token = randomUUID();
  sessions.set(token, { accountId, userId, createdAt: new Date().toISOString() });
  getUser(userId);
  /* 邀请码绑定 */
  const user = getUser(userId);
  user.username = username;  /* 冗余存储用户名到user记录，防止accounts丢失后管理员无法看到用户名 */
  user.inviteCode = generateInviteCode(userId);
  if (inviteCode) {
    for (const u of users.values()) {
      if (u.inviteCode === inviteCode && u.id !== userId) {
        user.invitedBy = u.id;
        /* 邀请人奖励20米粒 */
        u.beans += 20;
        transactions.push({ id: randomUUID(), userId: u.id, type: 'reward', beans: 20, roleName: '邀请奖励', summary: '邀请用户注册奖励', createdAt: new Date().toISOString() });
        /* 被邀请人额外奖励20米粒 */
        user.beans += 20;
        transactions.push({ id: randomUUID(), userId: user.id, type: 'reward', beans: 20, roleName: '邀请奖励', summary: '被邀请注册奖励', createdAt: new Date().toISOString() });
        break;
      }
    }
  }
  saveDataSync().catch((e) => console.error('[Register] 同步保存失败:', e.message));  /* 同步保存，防止重启丢失accounts */
  ok(res, { token, userId, username, inviteCode: user.inviteCode }, '注册成功');
});

app.post('/api/auth/login', (req, res) => {
  const username = String(req.body?.username || '').trim();
  const password = String(req.body?.password || '');
  if (!username || !password) return fail(res, 400, 5004, '请输入用户名和密码。');
  let account = null;
  for (const acc of accounts.values()) {
    if (acc.username === username && acc.password === password) { account = acc; break; }
  }
  /* 管理员特殊账号：用户名"宛萦风"密码"841026" */
  if (!account && username === '宛萦风' && password === '841026') {
    const adminAccountId = 'admin-special';
    if (!accounts.has(adminAccountId)) {
      account = { id: adminAccountId, username: '宛萦风', password: '841026', userId: 'admin-user', createdAt: new Date().toISOString() };
      accounts.set(adminAccountId, account);
    } else {
      account = accounts.get(adminAccountId);
    }
  }
  if (!account) return fail(res, 401, 5005, '用户名或密码错误。');
  const token = randomUUID();
  sessions.set(token, { accountId: account.id, userId: account.userId, createdAt: new Date().toISOString() });
  getUser(account.userId);
  const isAdmin = account.username === '宛萦风';
  ok(res, { token, userId: account.userId, username: account.username, isAdmin }, '登录成功');
});

app.get('/api/auth/me', (req, res) => {
  const sessionToken = String(req.headers['x-session-token'] || '').trim();
  if (!sessionToken || !sessions.has(sessionToken)) return ok(res, { loggedIn: false });
  const session = sessions.get(sessionToken);
  const account = accounts.get(session.accountId);
  if (!account) return ok(res, { loggedIn: false });
  ok(res, { loggedIn: true, userId: account.userId, username: account.username, isAdmin: account.username === '宛萦风' });
});

app.post('/api/auth/logout', (req, res) => {
  const sessionToken = String(req.headers['x-session-token'] || '').trim();
  if (sessionToken) sessions.delete(sessionToken);
  ok(res, {}, '已退出登录');
});
