/* ---- state ---- */
var sfState = {
  active: false,
  currentTab: 'following',
  posts: { following: [], recommended: [], gossip: [] },
  currentRole: null,
  isLoading: false,
  sideMenuOpen: false,
  userProfile: { posts: 0, followers: 0, following: 0, likes: 0, avatar: null },
  currentView: 'feed',
  userPosts: [],
  commentsCache: {},
  currentPostId: null,
  notifCache: null,
  loading: { following: false, recommended: false, gossip: false },
  followedRoles: [], // 已关注的角色 [{id, name, prompt, avatar}]
  likedPosts: [], // 点赞过的帖子记录
  savedPosts: [], // 收藏过的帖子记录
  profileTab: 'posts', // 个人主页当前标签页
};

var sfSaveFollowedRoles = function () {
  try { localStorage.setItem('sf_followed_roles', JSON.stringify(sfState.followedRoles)); } catch(e) {}
};

/* Save user posts to localStorage so they survive page refresh */
var sfSaveUserPosts = function () {
  try { localStorage.setItem('sf_user_posts', JSON.stringify(sfState.userPosts.slice(0, 200))); } catch(e) {}
};

/* Load user posts from localStorage */
var sfLoadUserPosts = function () {
  try {
    var saved = localStorage.getItem('sf_user_posts');
    if (saved) sfState.userPosts = JSON.parse(saved) || [];
  } catch(e) {}
};

/* Save comments cache to localStorage */
var sfSaveCommentsCache = function () {
  try { localStorage.setItem('sf_comments_cache', JSON.stringify(sfState.commentsCache)); } catch(e) {}
};

/* Load comments cache from localStorage */
var sfLoadCommentsCache = function () {
  try {
    var saved = localStorage.getItem('sf_comments_cache');
    if (saved) sfState.commentsCache = JSON.parse(saved) || {};
  } catch(e) {}
};

/* ---- cache versioning: invalidate old cached posts when code updates ---- */
var SF_CACHE_VERSION = 'v2_20260725';
try {
  var storedVer = localStorage.getItem('sf_cache_version');
  if (storedVer !== SF_CACHE_VERSION) {
    ['following', 'recommended', 'gossip'].forEach(function(t) {
      localStorage.removeItem('sf_posts_' + t);
    });
    localStorage.setItem('sf_cache_version', SF_CACHE_VERSION);
  }
} catch(e) {}

/* Load user posts and comments cache from localStorage on startup */
try { sfLoadUserPosts(); } catch(e) {}
try { sfLoadCommentsCache(); } catch(e) {}

