var wcCurrentTab = 'chats';
var wcImportList = [];

var wcFormatTime = function(ts) {
  if (!ts) return '';
  var d = new Date(ts);
  var now = new Date();
  var diff = now - d;
  if (diff < 60000) return '刚刚';
  if (diff < 3600000) return Math.floor(diff / 60000) + '分钟前';
  if (d.toDateString() === now.toDateString()) {
    var h = String(d.getHours());
    var m = String(d.getMinutes());
    while (h.length < 2) h = '0' + h;
    while (m.length < 2) m = '0' + m;
    return h + ':' + m;
  }
  return (d.getMonth() + 1) + '月' + d.getDate() + '日';
};

var wcStripMeta = function(str) {
  if (!str) return '';
  var s = String(str);
  /* remove <thinking>...</thinking> blocks */
  while (s.indexOf('<thinking>') !== -1) {
    var s1 = s.indexOf('<thinking>');
    var e1 = s.indexOf('</thinking>', s1);
    if (e1 === -1) break;
    s = s.slice(0, s1) + s.slice(e1 + 11);
  }
  /* remove <miyavoice>...</miyavoice> blocks */
  while (s.indexOf('<miyavoice>') !== -1) {
    var s2 = s.indexOf('<miyavoice>');
    var e2 = s.indexOf('</miyavoice>', s2);
    if (e2 === -1) break;
    s = s.slice(0, s2) + s.slice(e2 + 12);
  }
  /* remove any remaining HTML tags */
  while (s.indexOf('<') !== -1) {
    var lt = s.indexOf('<');
    var gt = s.indexOf('>', lt);
    if (gt === -1) break;
    s = s.slice(0, lt) + s.slice(gt + 1);
  }
  return s.trim();
};

