var wcRenderTab = function(tab) {
  wcCurrentTab = tab;
  var tabs = document.querySelectorAll('.wc-tab');
  for (var i = 0; i < tabs.length; i++) {
    tabs[i].classList.toggle('active', tabs[i].getAttribute('data-wc-tab') === tab);
  }
  var titles = { chats: '微信', contacts: '通讯录', discover: '朋友圈', me: '' };
  var titleEl = document.getElementById('wcHeaderTitle');
  if (titleEl) titleEl.textContent = titles[tab] || '';
  if (tab === 'chats') wcRenderChats();
  else if (tab === 'contacts') wcRenderContacts();
  else if (tab === 'discover') wcRenderDiscover();
  else if (tab === 'me') wcRenderMe();
};

var wcRenderChats = function() {
  var body = document.getElementById('wcBody');
  if (!body) return;
  var roles = (typeof state !== 'undefined' && state.roles) ? state.roles : [];
  if (!roles.length) {
    body.innerHTML = '<div class="wc-empty">还没有联系人<br>点击右上角 + 添加</div>';
    return;
  }
  var html = '<div class="wc-chat-list">';
  for (var i = 0; i < roles.length; i++) {
    var role = roles[i];
    var msgs = [];
    try { msgs = getMessages(role.id) || []; } catch(e) {}
    var lastMsg = msgs.length ? msgs[msgs.length - 1] : null;
    var preview = '点击开始聊天';
    if (lastMsg) {
      var content = wcStripMeta(lastMsg.content);
      if (content.indexOf('红包') === 0) content = '[红包]';
      else if (content.indexOf('转账') === 0) content = '[转账]';
      else if (content.indexOf('语音') === 0) content = '[语音]';
      else if (content.indexOf('旁白') === 0) content = '[旁白]';
      else if (content.indexOf('表情包') === 0) content = '[表情]';
      else if (content.indexOf('图片') === 0) content = '[图片]';
      preview = (lastMsg.role === 'user' ? '我: ' : '') + content.slice(0, 40);
    }
    var time = lastMsg ? wcFormatTime(lastMsg.createdAt) : '';
    var avatarHtml = '';
    if (role.avatar) {
      avatarHtml = '<img class="wc-chat-avatar" src="' + escapeHtml(role.avatar) + '" alt="" />';
    } else {
      avatarHtml = '<div class="wc-chat-avatar">' + escapeHtml(role.name ? role.name.charAt(0) : '?') + '</div>';
    }
    html += '<div class="wc-chat-item" data-wc-chat="' + escapeHtml(role.id) + '">' +
      avatarHtml +
      '<div class="wc-chat-content">' +
        '<div class="wc-chat-top">' +
          '<span class="wc-chat-name">' + escapeHtml(role.name || '未命名') + '</span>' +
          '<span class="wc-chat-time">' + time + '</span>' +
        '</div>' +
        '<div class="wc-chat-msg">' + escapeHtml(preview) + '</div>' +
      '</div>' +
    '</div>';
  }
  html += '</div>';
  body.innerHTML = html;
};

var wcRenderContacts = function() {
  var body = document.getElementById('wcBody');
  if (!body) return;
  var roles = (typeof state !== 'undefined' && state.roles) ? state.roles : [];
  if (!roles.length) {
    body.innerHTML = '<div class="wc-empty">通讯录为空</div>';
    return;
  }
  var html = '<div class="wc-contact-section">';
  html += '<div class="wc-contact-header">联系人</div>';
  for (var i = 0; i < roles.length; i++) {
    var role = roles[i];
    var avatarHtml = '';
    if (role.avatar) {
      avatarHtml = '<img class="wc-contact-avatar" src="' + escapeHtml(role.avatar) + '" alt="" />';
    } else {
      avatarHtml = '<div class="wc-contact-avatar">' + escapeHtml(role.name ? role.name.charAt(0) : '?') + '</div>';
    }
    html += '<div class="wc-contact-item" data-wc-chat="' + escapeHtml(role.id) + '">' +
      avatarHtml +
      '<span class="wc-contact-name">' + escapeHtml(role.name || '未命名') + '</span>' +
    '</div>';
  }
  html += '</div>';
  body.innerHTML = html;
};

var wcGetMoments = function() {
  try { return JSON.parse(localStorage.getItem('mochi_moments') || '[]'); }
  catch(e) { return []; }
};
var wcSaveMoments = function(list) {
  try { localStorage.setItem('mochi_moments', JSON.stringify(list)); } catch(e) {}
};
var wcGetProfile = function() {
  try {
    var p = JSON.parse(localStorage.getItem('mochi_wc_profile') || '{}');
    return { nickname: p.nickname || '微信用户', avatar: p.avatar || '', bio: p.bio || '这个人很懒，什么都没写' };
  } catch(e) { return { nickname: '微信用户', avatar: '', bio: '这个人很懒，什么都没写' }; }
};
var wcSaveProfile = function(p) {
  try { localStorage.setItem('mochi_wc_profile', JSON.stringify(p)); } catch(e) {}
};
var wcGetWallet = function() {
  try { return parseFloat(localStorage.getItem('mochi_wc_wallet') || '0'); }
  catch(e) { return 0; }
};
var wcSaveWallet = function(amount) {
  try { localStorage.setItem('mochi_wc_wallet', String(amount)); } catch(e) {}
};
var wcRenderDiscover = function() {
  var body = document.getElementById('wcBody');
  if (!body) return;
  var moments = wcGetMoments();
  var wcProfile = wcGetProfile();
  var nickname = wcProfile.nickname || '我';
  var avatarHtml = '';
  if (wcProfile.avatar) {
    avatarHtml = '<img class="wc-moment-avatar" src="' + escapeHtml(wcProfile.avatar) + '" alt="" />';
  } else {
    avatarHtml = '<div class="wc-moment-avatar">' + escapeHtml(nickname.charAt(0)) + '</div>';
  }
  var html = '<div style="background:rgba(255,255,255,0.75);backdrop-filter:blur(10px);padding:14px 16px;display:flex;align-items:center;gap:10px;border-radius:24px;margin-bottom:8px;box-shadow:0 2px 12px rgba(255,182,193,0.08);border:1px solid rgba(255,214,231,0.3)">' +
    avatarHtml +
    '<div style="flex:1;color:#B8A0AC;font-size:14px" onclick="wcShowPostBox()">分享这一刻...</div>' +
    '<button onclick="wcShowPostBox()" style="background:linear-gradient(135deg,#FFC7D9,#FFC7D9);color:#fff;border:none;padding:8px 20px;border-radius:20px;font-size:13px;cursor:pointer;font-weight:600;box-shadow:0 2px 8px rgba(255,182,193,0.3)">发表</button>' +
  '</div>';
  html += '<div id="wcPostBox" style="display:none;background:rgba(255,255,255,0.75);backdrop-filter:blur(10px);padding:16px;border-radius:24px;margin-bottom:8px;box-shadow:0 2px 12px rgba(255,182,193,0.08);border:1px solid rgba(255,214,231,0.3)">' +
    '<textarea id="wcPostInput" placeholder="这一刻的想法..." style="width:100%;min-height:80px;padding:12px;border:1px solid rgba(255,214,231,0.5);border-radius:16px;font-size:14px;resize:vertical;box-sizing:border-box;background:rgba(255,250,252,0.8);color:#6B4C5A"></textarea>' +
    '<div style="display:flex;justify-content:space-between;margin-top:8px">' +
      '<span style="font-size:12px;color:#B8A0AC">发表后AI自动生成评论和点赞（消耗1米粒）</span>' +
      '<button id="wcPostSubmit" onclick="wcSubmitPost()" style="background:linear-gradient(135deg,#FFC7D9,#FFC7D9);color:#fff;border:none;padding:8px 24px;border-radius:20px;font-size:13px;cursor:pointer;font-weight:600;box-shadow:0 2px 8px rgba(255,182,193,0.3)">发布</button>' +
    '</div>' +
  '</div>';
  if (!moments.length) {
    html += '<div class="wc-empty" style="padding:60px 20px;text-align:center;color:#C9A0B0">还没有朋友圈动态<br>点击上方发表第一条吧 🌸</div>';
  } else {
    html += '<div class="wc-moments-list">';
    for (var i = 0; i < moments.length; i++) {
      var m = moments[i];
      var mAvatar = '';
      if (m.avatar) {
        mAvatar = '<img class="wc-moment-avatar" src="' + escapeHtml(m.avatar) + '" alt="" />';
      } else {
        mAvatar = '<div class="wc-moment-avatar">' + escapeHtml((m.name || '我').charAt(0)) + '</div>';
      }
      html += '<div class="wc-moment-item" style="background:rgba(255,255,255,0.75);backdrop-filter:blur(10px);padding:14px 16px;border-radius:24px;margin-bottom:8px;box-shadow:0 2px 12px rgba(255,182,193,0.08);border:1px solid rgba(255,214,231,0.3);position:relative">' +
        '<div style="display:flex;gap:10px">' +
          mAvatar +
          '<div style="flex:1">' +
            '<div style="display:flex;justify-content:space-between;align-items:center">' +
              '<div style="font-weight:700;color:#E891A8;font-size:14px">' + escapeHtml(m.name || nickname) + '</div>' +
              '<button onclick="wcDeleteMoment(' + i + ')" style="background:rgba(255,200,200,0.3);border:1px solid rgba(255,150,150,0.4);color:#E88;padding:2px 10px;border-radius:12px;font-size:11px;cursor:pointer">删除</button>' +
            '</div>' +
            '<div style="margin-top:4px;font-size:14px;color:#6B4C5A;line-height:1.6;white-space:pre-wrap">' + escapeHtml(m.content) + '</div>' +
            '<div style="margin-top:6px;font-size:12px;color:#C9A0B0">' + escapeHtml(m.time || '刚刚') + '</div>';
      if (m.likes && m.likes > 0) {
        html += '<div style="margin-top:6px;font-size:12px;color:#E891A8">❤ ' + m.likes + '人赞</div>';
      }
      if (m.comments && m.comments.length) {
        html += '<div style="margin-top:8px;background:rgba(255,244,214,0.5);border-radius:16px;padding:10px 12px">';
        for (var j = 0; j < m.comments.length; j++) {
          var cm = m.comments[j];
          html += '<div style="font-size:13px;line-height:1.7;color:#6B4C5A"><span style="color:#E891A8;font-weight:700">' + escapeHtml(cm.name) + ':</span> ' + escapeHtml(cm.content) + '</div>';
        }
        html += '</div>';
      }
      html += '</div></div></div>';
    }
    html += '</div>';
  }
  body.innerHTML = html;
};
var wcShowPostBox = function() {
  var box = document.getElementById('wcPostBox');
  if (box) { box.style.display = 'block'; var input = document.getElementById('wcPostInput'); if (input) input.focus(); }
};
var wcSubmitPost = async function() {
  if (!authToken) { alert('游客不能使用此功能，请先注册登录。'); showAuthPage(); return; }
  var input = document.getElementById('wcPostInput');
  if (!input) return;
  var content = input.value.trim();
  if (!content) { if (typeof toast === 'function') toast('请输入内容'); return; }
  var btn = document.getElementById('wcPostSubmit');
  if (btn) { btn.textContent = '发布中...'; btn.disabled = true; }
  try {
    var wcRoles = (typeof state !== 'undefined' && state.roles) ? state.roles.map(function(r) { return { name: r.name || '未命名', description: r.description || r.prompt || '' }; }) : [];
    var result = await request('/moments/generate', { method: 'POST', body: JSON.stringify({ content: content, roles: wcRoles }) });
    var wcProfile = wcGetProfile();
    var moment = {
      content: content,
      name: wcProfile.nickname || '我',
      avatar: wcProfile.avatar || '',
      time: wcFormatTime(Date.now()),
      likes: result.likes || 0,
      comments: result.comments || []
    };
    var moments = wcGetMoments();
    moments.unshift(moment);
    if (moments.length > 50) moments.length = 50;
    wcSaveMoments(moments);
    if (typeof window.refreshServerUser === 'function') window.refreshServerUser();
    wcRenderDiscover();
  } catch(e) {
    if (typeof toast === 'function') toast(e.message || '发布失败');
  }
  if (btn) { btn.textContent = '发布'; btn.disabled = false; }
};

var wcRenderMe = function() {
  var body = document.getElementById('wcBody');
  if (!body) return;
  var wcProfile = wcGetProfile();
  var walletBalance = wcGetWallet();
  var nickname = wcProfile.nickname || '用户';
  var bio = wcProfile.bio || '这个人很懒，什么都没写';
  var avatarHtml = '';
  if (wcProfile.avatar) {
    avatarHtml = '<img class="wc-me-avatar" src="' + escapeHtml(wcProfile.avatar) + '" alt="" />';
  } else {
    avatarHtml = '<div class="wc-me-avatar">' + escapeHtml(nickname.charAt(0)) + '</div>';
  }
  body.innerHTML =
    '<div class="wc-me-profile" onclick="wcShowEditProfile()" style="cursor:pointer">' +
      avatarHtml +
      '<div class="wc-me-info">' +
        '<div class="wc-me-name">' + escapeHtml(nickname) + ' <span style="font-size:12px;color:#D4A0B8">›</span></div>' +
        '<div class="wc-me-id">' + escapeHtml(bio) + '</div>' +
      '</div>' +
    '</div>' +
    '<div class="wc-me-list">' +
      '<div class="wc-me-item"><span class="wc-me-icon">🌟</span><span class="wc-me-label">收藏</span><span class="wc-discover-arrow">›</span></div>' +
      '<div class="wc-me-item" onclick="wcRenderWallet()" style="cursor:pointer"><span class="wc-me-icon">🧧</span><span class="wc-me-label">钱包</span><span style="font-size:13px;color:#E891A8;font-weight:600">¥' + walletBalance.toFixed(2) + '</span><span class="wc-discover-arrow">›</span></div>' +
    '</div>' +
    '<div class="wc-me-list">' +
      '<div class="wc-me-item"><span class="wc-me-icon">🎀</span><span class="wc-me-label">装扮</span><span class="wc-discover-arrow">›</span></div>' +
      '<div class="wc-me-item"><span class="wc-me-icon">⚙️</span><span class="wc-me-label">设置</span><span class="wc-discover-arrow">›</span></div>' +
    '</div>';
};
var wcRenderWallet = function() {
  var body = document.getElementById('wcBody');
  if (!body) return;
  var balance = wcGetWallet();
  body.innerHTML =
    '<div style="padding:12px 0">' +
      '<div style="display:flex;align-items:center;margin-bottom:16px">' +
        '<button onclick="wcRenderMe()" style="background:rgba(255,255,255,0.6);border:1px solid rgba(255,214,231,0.3);color:#6B4C5A;padding:6px 14px;border-radius:16px;font-size:13px;cursor:pointer">‹ 返回</button>' +
        '<span style="flex:1;text-align:center;font-size:16px;font-weight:700;color:#6B4C5A">钱包</span>' +
      '</div>' +
      '<div style="background:linear-gradient(135deg,#FFC7D9,#FFC7D9);border-radius:24px;padding:24px;text-align:center;box-shadow:0 4px 20px rgba(255,182,193,0.2);margin-bottom:12px">' +
        '<div style="font-size:13px;color:rgba(255,255,255,0.8);margin-bottom:8px">零钱余额（元）</div>' +
        '<div style="font-size:36px;font-weight:700;color:#fff">' + balance.toFixed(2) + '</div>' +
      '</div>' +
      '<div style="background:rgba(255,255,255,0.75);backdrop-filter:blur(10px);border-radius:24px;padding:16px;margin-bottom:8px;box-shadow:0 2px 12px rgba(255,182,193,0.08);border:1px solid rgba(255,214,231,0.3)">' +
        '<div style="font-size:14px;color:#6B4C5A;font-weight:600;margin-bottom:12px">修改余额</div>' +
        '<div style="display:flex;gap:8px">' +
          '<input id="wcWalletInput" type="number" step="0.01" min="0" value="' + balance.toFixed(2) + '" placeholder="输入金额" style="flex:1;padding:10px 14px;border:1px solid rgba(255,214,231,0.5);border-radius:16px;font-size:15px;background:rgba(255,250,252,0.8);color:#6B4C5A;box-sizing:border-box" />' +
          '<button onclick="wcSaveWalletEdit()" style="background:linear-gradient(135deg,#FFC7D9,#FFC7D9);color:#fff;border:none;padding:10px 20px;border-radius:16px;font-size:14px;cursor:pointer;font-weight:600;box-shadow:0 2px 8px rgba(255,182,193,0.3)">保存</button>' +
        '</div>' +
        '<div style="margin-top:10px;display:flex;gap:8px;flex-wrap:wrap">' +
          '<button onclick="wcQuickSetWallet(100)" style="background:rgba(255,244,214,0.6);border:1px solid rgba(255,214,231,0.3);color:#6B4C5A;padding:6px 14px;border-radius:14px;font-size:12px;cursor:pointer">+100</button>' +
          '<button onclick="wcQuickSetWallet(1000)" style="background:rgba(255,244,214,0.6);border:1px solid rgba(255,214,231,0.3);color:#6B4C5A;padding:6px 14px;border-radius:14px;font-size:12px;cursor:pointer">+1000</button>' +
          '<button onclick="wcQuickSetWallet(10000)" style="background:rgba(255,244,214,0.6);border:1px solid rgba(255,214,231,0.3);color:#6B4C5A;padding:6px 14px;border-radius:14px;font-size:12px;cursor:pointer">+10000</button>' +
          '<button onclick="wcQuickSetWallet(0)" style="background:rgba(255,200,200,0.3);border:1px solid rgba(255,150,150,0.3);color:#E88;padding:6px 14px;border-radius:14px;font-size:12px;cursor:pointer">清零</button>' +
        '</div>' +
        '<div style="margin-top:10px;font-size:12px;color:#C9A0B0">虚拟余额，可随意设置。发红包将从此余额扣除。</div>' +
      '</div>' +
      '<div style="background:rgba(255,255,255,0.75);backdrop-filter:blur(10px);border-radius:24px;padding:16px;box-shadow:0 2px 12px rgba(255,182,193,0.08);border:1px solid rgba(255,214,231,0.3)">' +
        '<div style="font-size:14px;color:#6B4C5A;font-weight:600;margin-bottom:8px">使用说明</div>' +
        '<div style="font-size:12px;color:#B8A0AC;line-height:1.8">· 余额为虚拟数值，可随时修改\\n· 在聊天中发送红包将从此余额扣除\\n· 余额不足时无法发送红包</div>' +
      '</div>' +
    '</div>';
  var titleEl = document.getElementById('wcHeaderTitle');
  if (titleEl) titleEl.textContent = '钱包';
  var tabs = document.querySelectorAll('.wc-tab');
  for (var i = 0; i < tabs.length; i++) { tabs[i].classList.remove('active'); }
};
var wcSaveWalletEdit = function() {
  var input = document.getElementById('wcWalletInput');
  if (!input) return;
  var amount = parseFloat(input.value) || 0;
  if (amount < 0) amount = 0;
  wcSaveWallet(amount);
  if (typeof toast === 'function') toast('余额已更新为 ¥' + amount.toFixed(2));
  wcRenderWallet();
};
var wcQuickSetWallet = function(amount) {
  if (amount === 0) {
    wcSaveWallet(0);
    if (typeof toast === 'function') toast('余额已清零');
  } else {
    var current = wcGetWallet();
    wcSaveWallet(current + amount);
    if (typeof toast === 'function') toast('余额已增加 ¥' + amount.toFixed(2));
  }
  wcRenderWallet();
};
var wcTriggerAvatarUpload = function() {
  var f = document.getElementById('wcAvatarFile');
  if (f) f.click();
};
