/* 点击语音条展开/收起转文字 */
document.addEventListener('click', function(e) {
  var voiceMsg = e.target.closest('.mc-voice-msg');
  if (!voiceMsg) return;
  var transcript = voiceMsg.querySelector('.mc-voice-transcript');
  if (!transcript) return;
  if (transcript.style.display === 'none') {
    var rawText = voiceMsg.getAttribute('data-voice-text') || '';
    var toneMatch = rawText.match(/\uff08([^\uff09]*)\uff09$/);
    var mainText = rawText.replace(/\uff08[^\uff09]*\uff09$/, '').trim();
    var html = '<span class="vt-text">' + escapeHtml(mainText || rawText) + '</span>';
    if (toneMatch) {
      html += '<span class="vt-tone">\u8bed\u6c14\uff1a' + escapeHtml(toneMatch[1]) + '</span>';
    }
    transcript.innerHTML = html;
    transcript.style.display = 'block';
    var play = voiceMsg.querySelector('.mc-voice-play');
    if (play) play.textContent = '\u23f8';
  } else {
    transcript.style.display = 'none';
    var play = voiceMsg.querySelector('.mc-voice-play');
    if (play) play.textContent = '\u25b6';
  }
});


