/* 点击心形展开/收起心声 */
document.addEventListener('click', function(e) {
  var btn = e.target.closest('.mochi-voice-btn');
  if (!btn) return;
  var panel = document.getElementById('mochiVoicePanel');
  if (!panel) return;
  if (panel.classList.contains('show')) {
    panel.classList.remove('show');
    return;
  }
  var bar = document.getElementById('mochiVoiceBar');
  var raw = bar ? (bar.getAttribute('data-voice-text') || '') : '';
  if (!raw || !raw.trim()) {
    panel.innerHTML = '<span class="mv-line" style="color:#bbb">暂无心声</span>';
    panel.classList.add('show');
    return;
  }
  var lines = raw.split('\\n').filter(function(l) { return l.trim(); });
  var html = '';
  lines.forEach(function(line) {
    var t = line.trim();
    if (!t) return;
    var m = t.match(/^(心情|好感|想法|小动作)[：:](.*)/);
    if (m) {
      html += '<span class="mv-line"><span class="mv-label">' + escapeHtml(m[1]) + '：</span>' + escapeHtml(m[2].trim()) + '</span>';
    } else {
      html += '<span class="mv-line">' + escapeHtml(t) + '</span>';
    }
  });
  panel.innerHTML = html;
  panel.classList.add('show');
});


/* === 长按消息：删除/编辑单条气泡 === */
var mochiLongPressTimer = null;
var mochiLongPressTarget = null;

document.addEventListener('touchstart', function(e) {
  var bubble = e.target.closest('.chat-bubble[data-bubble-idx]');
  if (!bubble) {
    var narration = e.target.closest('.mc-narration-row');
    if (narration) {
      mochiLongPressTarget = narration;
      mochiLongPressTimer = setTimeout(function() {
        if (mochiLongPressTarget === narration) {
          e.preventDefault();
          mochiDeleteNarration(narration);
        }
      }, 600);
    }
    return;
  }
  mochiLongPressTarget = bubble;
  mochiLongPressTimer = setTimeout(function() {
    if (mochiLongPressTarget === bubble) {
      e.preventDefault();
      mochiShowBubbleMenu(bubble);
    }
  }, 600);
}, { passive: true });

document.addEventListener('touchend', function() {
  if (mochiLongPressTimer) { clearTimeout(mochiLongPressTimer); mochiLongPressTimer = null; }
});

document.addEventListener('mousedown', function(e) {
  var bubble = e.target.closest('.chat-bubble[data-bubble-idx]');
  if (!bubble) {
    var narration = e.target.closest('.mc-narration-row');
    if (narration) {
      mochiLongPressTarget = narration;
      mochiLongPressTimer = setTimeout(function() {
        if (mochiLongPressTarget === narration) {
          mochiDeleteNarration(narration);
        }
      }, 600);
    }
    return;
  }
  mochiLongPressTarget = bubble;
  mochiLongPressTimer = setTimeout(function() {
    if (mochiLongPressTarget === bubble) {
      mochiShowBubbleMenu(bubble);
    }
  }, 600);
});

document.addEventListener('mouseup', function() {
  if (mochiLongPressTimer) { clearTimeout(mochiLongPressTimer); mochiLongPressTimer = null; }
});

document.addEventListener('mousemove', function() {
  if (mochiLongPressTimer) { clearTimeout(mochiLongPressTimer); mochiLongPressTimer = null; }
});

var mochiDeleteNarration = function(narrationEl) {
  var msgId = narrationEl.getAttribute('data-msg-id');
  if (!msgId) return;
  var role = activeRole();
  if (!role) return;
  if (!confirm('确认删除这条旁白？')) return;
  var messages = getMessages(role.id);
  state.conversations[getConversationKey(role.id)] = messages.filter(function(m) { return m.id !== msgId; });
  api.cleanupMemories({ roleId: role.id, sourceConversationId: role.id, sourceMessageIds: [msgId] }).catch(function() { return null; });
  persist();
  renderMessages();
  toast('旁白已删除');
};

var mochiShowBubbleMenu = function(bubble) {
  var msgId = bubble.getAttribute('data-msg-id');
  var bubbleIdx = parseInt(bubble.getAttribute('data-bubble-idx'), 10) || 0;
  var menu = document.getElementById('bubbleMenuDialog');
  if (!menu) return;
  menu.dataset.msgId = msgId;
  menu.dataset.bubbleIdx = bubbleIdx;
  menu.showModal();
};

var mochiGetVisibleLines = function(content) {
  return mochiStripMetaTags(content).split('\\n').filter(function(l) { return l.trim(); });
};

var mochiRebuildContent = function(originalContent, newLines) {
  var voice = mochiExtractVoice(originalContent);
  var voiceBlock = voice ? '\\n<miyavoice>\\n' + voice + '\\n</miyavoice>' : '';
  return newLines.join('\\n') + voiceBlock;
};

var mochiDeleteBubble = function(msgId, bubbleIdx) {
  var role = activeRole();
  if (!role) return;
  var messages = getMessages(role.id);
  var msg = messages.find(function(m) { return m.id === msgId; });
  if (!msg) return;
  var lines = mochiGetVisibleLines(msg.content);
  if (bubbleIdx < 0 || bubbleIdx >= lines.length) return;
  lines.splice(bubbleIdx, 1);
  if (lines.length === 0) {
    var _delKey = getConversationKey(role.id);
    state.conversations[_delKey] = messages.filter(function(m) { return m.id !== msgId; });
    api.cleanupMemories({ roleId: role.id, sourceConversationId: role.id, sourceMessageIds: [msgId] }).catch(function() { return null; });
  } else {
    msg.content = mochiRebuildContent(msg.content, lines);
  }
  persist();
  renderMessages();
  renderMemories();
  toast('\u5df2\u5220\u9664');
};

var mochiEditBubble = function(msgId, bubbleIdx, newText) {
  var role = activeRole();
  if (!role) return;
  var messages = getMessages(role.id);
  var msg = messages.find(function(m) { return m.id === msgId; });
  if (!msg) return;
  var lines = mochiGetVisibleLines(msg.content);
  if (bubbleIdx < 0 || bubbleIdx >= lines.length) return;
  lines[bubbleIdx] = newText.trim();
  msg.content = mochiRebuildContent(msg.content, lines);
  persist();
  renderMessages();
  /* Cleanup memories associated with this message (will be re-extracted on next round) */
  api.cleanupMemories({ roleId: role.id, sourceConversationId: role.id, sourceMessageIds: [msgId] }).catch(function() { return null; });
  toast('\u5df2\u4fee\u6539\uff0c\u5173\u8054\u8bb0\u5fc6\u5c06\u91cd\u65b0\u751f\u6210\u3002');
};

