var mochiStickerActiveTab = 'myimg';

var renderStickerPanel = function() {
  var panel = document.getElementById('stickerPanel');
  if (!panel) return;
  var allPacks = MOCHI_STICKER_PACKS.slice();
  if (state.customStickers && state.customStickers.length) {
    allPacks.push({ id: 'custom', name: '自定义', items: state.customStickers });
  }
  var tabsHtml = '<div class="mc-sticker-tabs">';
  for (var i = 0; i < allPacks.length; i++) {
    var p = allPacks[i];
    tabsHtml += '<button class="mc-sticker-tab' + (p.id === mochiStickerActiveTab ? ' active' : '') + '" data-sticker-tab="' + p.id + '" type="button">' + escapeHtml(p.name) + '</button>';
  }
  tabsHtml += '</div>';
  var activePack = null;
  for (var j = 0; j < allPacks.length; j++) {
    if (allPacks[j].id === mochiStickerActiveTab) { activePack = allPacks[j]; break; }
  }
  if (!activePack && allPacks.length) activePack = allPacks[0];
  var gridHtml = '<div class="mc-sticker-grid">';
  if (activePack && activePack.items) {
    for (var k = 0; k < activePack.items.length; k++) {
      var item = activePack.items[k];
      gridHtml += '<div class="mc-sticker-item" data-sticker-name="' + escapeHtml(item.name) + '">';
      if (item.url) {
        gridHtml += '<img src="' + escapeHtml(item.url) + '" alt="' + escapeHtml(item.name) + '" loading="lazy" />';
      } else {
        gridHtml += '<div class="mc-sticker-item-emoji">' + (item.emoji || '❓') + '</div>';
      }
      gridHtml += '<span class="mc-sticker-item-name">' + escapeHtml(item.name) + '</span></div>';
    }
  }
  gridHtml += '</div>';
  panel.innerHTML = gridHtml + tabsHtml;
  panel.querySelectorAll('[data-sticker-tab]').forEach(function(btn) {
    btn.addEventListener('click', function() {
      mochiStickerActiveTab = btn.getAttribute('data-sticker-tab');
      renderStickerPanel();
    });
  });
  panel.querySelectorAll('[data-sticker-name]').forEach(function(el) {
    el.addEventListener('click', function() {
      var name = el.getAttribute('data-sticker-name');
      sendSticker(name);
    });
  });
};

var toggleFuncPanel = function() {
  var panel = document.getElementById('funcPanel');
  var toggle = document.getElementById('plusToggle');
  if (!panel || !toggle) return;
  closeStickerPanel();
  if (panel.classList.contains('open')) {
    panel.classList.remove('open');
    toggle.classList.remove('active');
  } else {
    panel.classList.add('open');
    toggle.classList.add('active');
  }
};

var closeFuncPanel = function() {
  var panel = document.getElementById('funcPanel');
  var toggle = document.getElementById('plusToggle');
  if (panel) panel.classList.remove('open');
  if (toggle) toggle.classList.remove('active');
};

var toggleStickerPanel = function() {
  var panel = document.getElementById('stickerPanel');
  if (!panel) return;
  closeFuncPanel();
  if (panel.classList.contains('open')) {
    panel.classList.remove('open');
  } else {
    renderStickerPanel();
    panel.classList.add('open');
  }
};

var closeStickerPanel = function() {
  var panel = document.getElementById('stickerPanel');
  if (panel) panel.classList.remove('open');
};

var closeAllPanels = function() {
  closeFuncPanel();
  closeStickerPanel();
};

var sendImage = function() {
  var role = activeRole();
  if (!role) { toast('请先创建或选择一个角色。'); return; }
  var fileInput = document.getElementById('imageFileInput');
  if (!fileInput) {
    fileInput = document.createElement('input');
    fileInput.type = 'file';
    fileInput.id = 'imageFileInput';
    fileInput.accept = 'image/*';
    fileInput.style.display = 'none';
    document.body.appendChild(fileInput);
    fileInput.addEventListener('change', function(e) {
      var file = e.target.files[0];
      if (!file) return;
      if (file.size > 10 * 1024 * 1024) { toast('图片不能超过10MB。'); fileInput.value = ''; return; }
      var img = new Image();
      img.onload = function() {
        var MAX_W = 768, MAX_H = 768;
        var w = img.width, h = img.height;
        if (w > MAX_W || h > MAX_H) {
          var ratio = Math.min(MAX_W / w, MAX_H / h);
          w = Math.round(w * ratio);
          h = Math.round(h * ratio);
        }
        var canvas = document.createElement('canvas');
        canvas.width = w;
        canvas.height = h;
        var ctx = canvas.getContext('2d');
        ctx.drawImage(img, 0, 0, w, h);
        var compressed = canvas.toDataURL('image/jpeg', 0.6);
        var r = activeRole();
        if (!r) return;
        var msgs = getMessages(r.id);
        msgs.push({ id: uuid(), role: 'user', content: '图片-' + compressed + '|', createdAt: Date.now() });
        persist();
        renderMessages();
        closeFuncPanel();
        toast('图片已发送。');
      };
      img.onerror = function() { toast('图片加载失败。'); };
      var reader = new FileReader();
      reader.onload = function(ev) { img.src = ev.target.result; };
      reader.readAsDataURL(file);
      fileInput.value = '';
    });
  }
  fileInput.value = '';
  fileInput.click();
  closeFuncPanel();
};

var sendRedPacket = function() {
  var role = activeRole();
  if (!role) { toast('请先创建或选择一个角色。'); return; }
  var walletBalance = wcGetWallet();
  var type = prompt('红包类型：拼手气 / 专属（直接输入金额则为普通红包）\\n当前钱包余额：¥' + walletBalance.toFixed(2), '拼手气');
  if (!type) return;
  type = type.trim();
  var messages = getMessages(role.id);
  var totalAmount = 0;
  if (type === '拼手气') {
    var amount = prompt('红包金额（元）：', '8.88');
    if (!amount) return;
    totalAmount = parseFloat(amount) || 0;
    if (totalAmount > walletBalance) { toast('钱包余额不足！当前余额：¥' + walletBalance.toFixed(2)); return; }
    var count = prompt('红包个数：', '3');
    if (!count) return;
    var wish = prompt('祝福语（可选）：', '恭喜发财') || '恭喜发财';
    messages.push({ id: uuid(), role: 'user', content: '红包-拼手气|' + amount + '|' + count + '|' + wish, createdAt: Date.now() });
  } else if (type === '专属') {
    var amount = prompt('红包金额（元）：', '13.14');
    if (!amount) return;
    totalAmount = parseFloat(amount) || 0;
    if (totalAmount > walletBalance) { toast('钱包余额不足！当前余额：¥' + walletBalance.toFixed(2)); return; }
    var target = prompt('给谁：', role ? role.name : '');
    if (!target) return;
    var wish = prompt('祝福语（可选）：', '专属红包') || '专属红包';
    messages.push({ id: uuid(), role: 'user', content: '红包-专属|' + amount + '|' + target + '|' + wish, createdAt: Date.now() });
  } else {
    var amount = type;
    totalAmount = parseFloat(amount) || 0;
    if (totalAmount > walletBalance) { toast('钱包余额不足！当前余额：¥' + walletBalance.toFixed(2)); return; }
    var note = prompt('备注（可选）：', '红包') || '红包';
    messages.push({ id: uuid(), role: 'user', content: '红包-' + amount + '|' + note, createdAt: Date.now() });
  }
  wcSaveWallet(walletBalance - totalAmount);
  toast('红包已发出，扣除 ¥' + totalAmount.toFixed(2) + '，剩余 ¥' + (walletBalance - totalAmount).toFixed(2));
  persist();
  renderMessages();
  closeFuncPanel();
};

