var handleFuncAction = function(func) {
  closeFuncPanel();
  setTimeout(function() {
    if (func === 'image') sendImage();
    else if (func === 'redpacket') sendRedPacket();
    else if (func === 'transfer') sendTransfer();
    else if (func === 'sticker') toggleStickerPanel();
    else if (func === 'voice') sendVoice();
    else if (func === 'narration') sendNarration();
  }, 250);
};

