/* 复制邀请码 */
document.getElementById('copyInviteCodeBtn')?.addEventListener('click', async () => {
  const code = document.getElementById('myInviteCode')?.textContent || '';
  if (code && code !== '-') {
    try { await navigator.clipboard.writeText(code); alert('邀请码已复制：' + code); }
    catch (e) { alert('请手动复制：' + code); }
  }
});
/* 复制邀请链接 */
document.getElementById('copyInviteLinkBtn')?.addEventListener('click', async () => {
  const code = document.getElementById('myInviteCode')?.textContent || '';
  if (code && code !== '-') {
    const link = window.location.origin + '/?invite=' + encodeURIComponent(code);
    try { await navigator.clipboard.writeText(link); alert('邀请链接已复制：\\n' + link + '\\n\\n分享给好友，他们注册时填入邀请码即可！'); }
    catch (e) {
      const textarea = document.createElement('textarea');
      textarea.value = link;
      document.body.appendChild(textarea);
      textarea.select();
      try { document.execCommand('copy'); alert('邀请链接已复制！'); } catch (e2) { alert('请手动复制：' + link); }
      document.body.removeChild(textarea);
    }
  } else {
    alert('邀请码加载中，请稍后再试');
  }
});

