    + (genderText ? '<p style="margin:0 0 20px;font-size:13px;color:#999">' + genderText + '</p>' : '<p style="margin:0 0 20px;font-size:13px;color:#999">\u70b9\u51fb\u4e0b\u65b9\u67e5\u770b\u8be6\u60c5</p>')
    + '<div style="display:flex;gap:10px">'
