    + '<button id="roleInfoSettingBtn" type="button" style="flex:1;padding:12px;background:linear-gradient(135deg,#FFD1DC,#FFC7D9);color:#fff;border:none;border-radius:12px;cursor:pointer;font-size:15px;font-weight:600">\u89d2\u8272\u8bbe\u7f6e</button>'
