app.post('/api/apps', (req, res) => {
  const user = getUser(req.userId);
  const name = String(req.body?.name || '').trim().slice(0, 40);
  const icon = String(req.body?.icon || '📦').trim().slice(0, 200000);
  const description = String(req.body?.description || '').trim().slice(0, 200);
  const html = String(req.body?.html || '').trim();
  if (!name) return res.status(400).json({ error: '请填写APP名称' });
  if (!html || html.length < 20) return res.status(400).json({ error: '请提供有效的HTML代码' });
  if (html.length > 200000) return res.status(400).json({ error: 'HTML代码过长（上限200KB）' });
  const app = {
    id: randomUUID(),
    name: name,
    icon: icon,
    description: description,
    html: html,
    author: user?.nickname || (req.userId ? '用户' + req.userId.slice(-4) : '匿名'),
    authorId: req.userId || null,
    createdAt: new Date().toISOString(),
    installs: 0
  };
  communityApps.unshift(app);
  if (communityApps.length > 500) communityApps.length = 500;
  saveDataNow();
  ok(res, { id: app.id, name: app.name });
});

app.get('/api/user/me', (req, res) => {
  /* 无session时，如果userId对应的用户已存在，仍返回其真实数据 */
  if (!req.accountId) {
    /* 检查是否已有该用户记录（不创建新用户） */
    if (users.has(req.userId)) {
      const existingUser = users.get(req.userId);
      const vipInfo = getVipInfo(existingUser.id);
      const username = getUsername(existingUser.id) || null;
      ok(res, { id: existingUser.id, beans: existingUser.beans, transactions: transactions.filter((item) => item.userId === existingUser.id).slice(-50).reverse(), vip: vipInfo, inviteCode: existingUser.inviteCode || null, username: username });
      return;
    }
    /* 用户不存在时返回0，不自动创建 */
    ok(res, { id: req.userId, beans: 0, transactions: [], vip: { isActive: false, type: null, discount: 1, dailyBeans: 0, expireDate: null }, inviteCode: null });
    return;
  }
  const user = getUser(req.userId);
  const vipInfo = getVipInfo(user.id);
  const username = getUsername(user.id) || null;
  ok(res, { id: user.id, beans: user.beans, transactions: transactions.filter((item) => item.userId === user.id).slice(-50).reverse(), vip: vipInfo, inviteCode: user.inviteCode || null, username: username });
});

