/* 创建充值验证订单 - 用户扫码付款后提交交易号 */
app.post('/api/user/recharge/callback', (req, res) => {
  const amount = Number(req.body?.amount);
  const transactionId = String(req.body?.transactionId || '').trim();
  const packageItem = config.rechargePackages.find((item) => item.amount === amount);
  if (!packageItem) return fail(res, 400, 4001, '充值套餐参数不正确。');
  if (!transactionId) return fail(res, 400, 4002, '请输入付款备注ID（交易号）。');
  const user = getUser(req.userId);
  const username = getUsername(user.id) || user.id;
  const verification = {
    id: randomUUID(),
    userId: user.id,
    username: username,
    amount: packageItem.amount,
    beans: packageItem.beans,
    transactionId: transactionId,
    status: 'pending',
    createdAt: new Date().toISOString(),
    reviewedAt: null,
    reviewNote: ''
  };
  paymentVerifications.unshift(verification);
  saveDataSync().catch(()=>{});
  ok(res, { verificationId: verification.id, status: 'pending' }, '充值订单已提交，请等待管理员审核。');
});

