const ADMIN_PASSWORD = process.env.ADMIN_PASSWORD || '841026';

app.post('/api/admin/login', (req, res) => {
  const password = String(req.body?.password || '');
  const authToken = String(req.body?.authToken || '').trim();
  /* 方式1: 通过 auth token 登录（管理员从主站跳转过来） */
  if (authToken && sessions.has(authToken)) {
    const session = sessions.get(authToken);
    const account = accounts.get(session.accountId);
    if (account && account.username === '宛萦风') {
      const token = randomUUID();
      ok(res, { token });
      return;
    }
  }
  /* 方式2: 通过密码登录 */
  if (password !== ADMIN_PASSWORD) return fail(res, 401, 4003, '管理员密码错误。');
  const token = randomUUID();
  ok(res, { token });
});

