app.post('/api/admin/verifications/:id/approve', adminAuth, async (req, res) => {
  const verificationId = req.params.id;
  const note = String(req.body?.note || '').trim();
  const verification = paymentVerifications.find((v) => v.id === verificationId);
  if (!verification) return fail(res, 404, 4005, '订单不存在。');
  if (verification.status !== 'pending') return fail(res, 400, 4006, `订单已处理（当前状态：${verification.status}）。`);
  verification.status = 'approved';
  verification.reviewedAt = new Date().toISOString();
  verification.reviewNote = note;
  const user = getUser(verification.userId);
  user.beans += verification.beans;
  stats.totalRechargeCny += verification.amount;
  /* 如果是VIP会员订单，激活会员 */
  if (verification.vipType && VIP_PACKAGES[verification.vipType]) {
    const vipPkg = VIP_PACKAGES[verification.vipType];
    const now = new Date();
    const currentExpire = user.vipExpire ? new Date(user.vipExpire) : now;
    const baseDate = currentExpire > now ? currentExpire : now;
    user.vipType = verification.vipType;
    user.vipExpire = new Date(baseDate.getTime() + vipPkg.days * 24 * 60 * 60 * 1000).toISOString();
  }
  transactions.push({
    id: randomUUID(),
    userId: user.id,
    type: 'recharge',
    beans: verification.beans,
    amount: verification.amount,
    roleName: '充值中心',
    summary: `充值 ${verification.amount} 元（交易号：${verification.transactionId}），到账 ${verification.beans} 米粒`,
    createdAt: new Date().toISOString()
  });
  /* 邀请人首充返点10% */
  if (!user.firstRechargeDone && user.invitedBy) {
    user.firstRechargeDone = true;
    const inviter = getUser(user.invitedBy);
    if (inviter) {
      const inviteReward = Math.floor(verification.beans * 0.1);
      inviter.beans += inviteReward;
      transactions.push({ id: randomUUID(), userId: inviter.id, type: 'reward', beans: inviteReward, roleName: '邀请奖励', summary: '被邀请人首充返点', createdAt: new Date().toISOString() });
      /* 被邀请人首充额外赠送10% */
      user.beans += Math.floor(verification.beans * 0.1);
      transactions.push({ id: randomUUID(), userId: user.id, type: 'reward', beans: Math.floor(verification.beans * 0.1), roleName: '邀请奖励', summary: '首充额外赠送', createdAt: new Date().toISOString() });
    }
  } else {
    user.firstRechargeDone = true;
  }
  await saveDataSync();
  ok(res, { approved: true, userId: user.id, beans: user.beans }, '已审批通过，米粒已发放。');
});

app.post('/api/admin/verifications/:id/reject', adminAuth, (req, res) => {
  const verificationId = req.params.id;
  const note = String(req.body?.note || '').trim();
  const verification = paymentVerifications.find((v) => v.id === verificationId);
  if (!verification) return fail(res, 404, 4005, '订单不存在。');
  if (verification.status !== 'pending') return fail(res, 400, 4006, `订单已处理（当前状态：${verification.status}）。`);
  verification.status = 'rejected';
  verification.reviewedAt = new Date().toISOString();
  verification.reviewNote = note;
  saveData();
  ok(res, { rejected: true }, '订单已拒绝。');
});

