/* 创建剧本（草稿） */
app.post('/api/novel-games/create', (req, res) => {
  const { name, category, tags, difficulty, description, coverGradient, accentColor, world, player, npcs, objective, systemPrompt } = req.body || {};
  if (!name || !String(name).trim()) return fail(res, 400, 4007, '请填写剧本名称。');
  if (!systemPrompt || !String(systemPrompt).trim()) return fail(res, 400, 4007, '请填写核心系统提示词。');
  const user = getUser(req.userId);
  const profile = userProfiles.get(req.userId) || {};
  const script = {
    id: 'user-' + Date.now() + '-' + Math.random().toString(36).slice(2, 8),
    name: String(name).slice(0, 60),
    category: String(category || '用户创作').slice(0, 30),
    tags: Array.isArray(tags) ? tags.slice(0, 8).map(t => String(t).slice(0, 12)) : [],
    difficulty: ['简单','中等','困难'].includes(difficulty) ? difficulty : '中等',
    description: String(description || '').slice(0, 500),
    coverGradient: Array.isArray(coverGradient) && coverGradient.length >= 2 ? coverGradient.slice(0, 2) : ['#667eea','#764ba2'],
    accentColor: String(accentColor || '#667eea').slice(0, 20),
    world: world || {},
    player: player || { customizable: ['name'], defaultStats: {}, startingItems: [] },
    npcs: Array.isArray(npcs) ? npcs.slice(0, 20) : [],
    objective: Array.isArray(objective) ? objective.slice(0, 5) : [],
    systemPrompt: String(systemPrompt).slice(0, 20000),
    ownerId: req.userId,
    uploaderNickname: profile.nickname || user.username || '匿名用户',
    status: 'draft',
    reviewNote: '',
    playCount: 0,
    earnings: 0,
    createdAt: new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  userNovelScripts.unshift(script);
  saveData();
  ok(res, script, '剧本草稿已保存');
});

/* 编辑剧本 */
app.put('/api/novel-games/user/:id', (req, res) => {
  const script = userNovelScripts.find(s => s.id === req.params.id && s.ownerId === req.userId);
  if (!script) return fail(res, 404, 4041, '剧本不存在或无权限修改');
  if (script.status === 'approved') return fail(res, 400, 4010, '已上线的剧本不能直接编辑，如需修改请先撤回');
  const { name, category, tags, difficulty, description, coverGradient, accentColor, world, player, npcs, objective, systemPrompt } = req.body || {};
  if (name !== undefined) script.name = String(name).slice(0, 60);
  if (category !== undefined) script.category = String(category).slice(0, 30);
  if (tags !== undefined) script.tags = Array.isArray(tags) ? tags.slice(0, 8).map(t => String(t).slice(0, 12)) : [];
  if (difficulty !== undefined) script.difficulty = ['简单','中等','困难'].includes(difficulty) ? difficulty : script.difficulty;
  if (description !== undefined) script.description = String(description).slice(0, 500);
  if (coverGradient !== undefined) script.coverGradient = Array.isArray(coverGradient) && coverGradient.length >= 2 ? coverGradient.slice(0, 2) : script.coverGradient;
  if (accentColor !== undefined) script.accentColor = String(accentColor).slice(0, 20);
  if (world !== undefined) script.world = world || {};
  if (player !== undefined) script.player = player || {};
  if (npcs !== undefined) script.npcs = Array.isArray(npcs) ? npcs.slice(0, 20) : [];
  if (objective !== undefined) script.objective = Array.isArray(objective) ? objective.slice(0, 5) : [];
  if (systemPrompt !== undefined) script.systemPrompt = String(systemPrompt).slice(0, 20000);
  script.updatedAt = new Date().toISOString();
  saveData();
  ok(res, script, '剧本已更新');
});

