/* 提交审核 */
app.post('/api/novel-games/:id/submit', (req, res) => {
  const script = userNovelScripts.find(s => s.id === req.params.id && s.ownerId === req.userId);
  if (!script) return fail(res, 404, 4041, '剧本不存在或无权限操作');
  if (script.status !== 'draft' && script.status !== 'rejected') {
    return fail(res, 400, 4011, '当前状态不能提交审核（仅草稿或被拒绝状态可提交）');
  }
  if (!script.systemPrompt || script.systemPrompt.trim().length < 50) {
    return fail(res, 400, 4012, '系统提示词太短，请完善后提交（至少50字）');
  }
  script.status = 'pending';
  script.reviewNote = '';
  script.updatedAt = new Date().toISOString();
  saveData();
  ok(res, { status: 'pending' }, '剧本已提交审核，请等待管理员审核');
});

