app.post('/api/social-reward/submit', (req, res) => {
  const { platform, postUrl, likes } = req.body || {};
  if (!platform || !['douyin', 'kuaishou', 'xiaohongshu'].includes(platform)) {
    return fail(res, 400, 7001, '请选择有效的平台。');
  }
  if (!postUrl) return fail(res, 400, 7002, '请输入帖子链接。');
  const likeCount = Number(likes) || 0;
  if (likeCount < 200) return fail(res, 400, 7003, '点赞数需达到200以上才能申请奖励。');
  const user = getUser(req.userId);
  if (isGuestUser(req.userId)) return fail(res, 403, 4030, '游客不能使用此功能，请先注册登录。');
  /* 检查是否已申请过同一链接 */
  const existing = socialRewards.find(r => r.userId === user.id && r.postUrl === postUrl);
  if (existing) return fail(res, 400, 7004, '该帖子已申请过奖励。');
  const reward = {
    id: randomUUID(), userId: user.id, platform, postUrl, likes: likeCount,
    status: 'pending', beans: 50, createdAt: new Date().toISOString(), reviewedAt: null
  };
  socialRewards.unshift(reward);
  saveData();
  ok(res, { rewardId: reward.id, status: 'pending' }, '申请已提交，请等待审核。');
});

