app.post('/api/memories/extract', async (req, res) => {
  const { roleId, roleName, messages } = req.body || {};
  const activeRoleId = String(roleId || 'default-role').slice(0, 80);
  const allMessages = Array.isArray(messages) ? messages.slice(-30) : [];

  if (allMessages.length < 2) {
    return fail(res, 400, 4005, '\u5bf9\u8bdd\u8bb0\u5f55\u592a\u5c11\uff0c\u65e0\u6cd5\u603b\u7ed3\u8bb0\u5fc6\u3002');
  }

  /* \u6784\u5efa\u5bf9\u8bdd\u6458\u5f55 */
  const excerptLines = allMessages.map((m) => {
    const who = m.role === 'user' ? '\u7528\u6237' : (roleName || '\u89d2\u8272');
    return who + ': ' + String(m.content || '').replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim();
  }).filter(l => l.trim());
  const excerpt = excerptLines.join('\n');

  if (excerpt.trim().length < 5) {
    return fail(res, 400, 4006, '\u5bf9\u8bdd\u5185\u5bb9\u592a\u5c11\uff0c\u65e0\u6cd5\u603b\u7ed3\u8bb0\u5fc6\u3002');
  }

  let segments = [];
  if (config.upstreamKey && !config.upstreamKey.includes('\u8bf7\u586b\u5199')) {
    try {
      segments = await summarizeMultipleMemoriesByAI(excerpt, roleName);
      console.log('[Memory] Manual extract AI result: ' + segments.length + ' segments');
    } catch(e) {
      console.error('[Memory] Manual extract AI error:', e.message);
    }
  }

  /* AI \u5931\u8d25\u65f6\u56de\u9000\u5230\u5355\u6761\u8bb0\u53d9\u6587\u5151\u5e95 */
  if (!segments.length) {
    const fallback = summarizeMemoryNarrativeFallback(excerpt, roleName);
    if (fallback) segments = [fallback];
  }

  if (!segments.length) {
    return fail(res, 500, 4007, '\u8bb0\u5fc6\u603b\u7ed3\u5931\u8d25\uff0c\u8bf7\u7a0d\u540e\u91cd\u8bd5\u3002');
  }

  ok(res, { segments, roleId: activeRoleId, roleName }, '\u8bb0\u5fc6\u5df2\u751f\u6210\uff0c\u8bf7\u67e5\u770b\u540e\u4fdd\u5b58');
});

