app.get('/api/community/roles', (req, res) => {
  const keyword = String(req.query.keyword || '').trim().toLowerCase();
  const tagFilter = String(req.query.tag || '').trim().toLowerCase();
  const scope = String(req.query.scope || 'public'); // public | mine | all
  const userProfile = userProfiles.get(req.userId) || { nickname: '体验用户' };
  let list = communityRoles.filter((role) => {
    // 私密角色只有 owner 自己可见
    if (role.isPublic === false && role.ownerId !== req.userId) return false;
    if (scope === 'mine') return role.ownerId === req.userId;
    if (scope === 'public') return role.isPublic !== false;
    // all: 公开 + 自己的私密
    return role.isPublic !== false || role.ownerId === req.userId;
  });
  if (keyword) list = list.filter((role) => `${role.name} ${role.description} ${role.prompt} ${(role.tags || []).join(' ')}`.toLowerCase().includes(keyword));
  if (tagFilter) list = list.filter((role) => (role.tags || []).some((t) => String(t).toLowerCase() === tagFilter));
  ok(res, { list, total: list.length, page: 1, pageSize: 60, myNickname: userProfile.nickname });
});

app.post('/api/community/roles', (req, res) => {
  const { name, gender, description, prompt, avatar, coverImage, orientation, tags, backgroundStory, isPublic } = req.body || {};
  if (!name || !prompt) return fail(res, 400, 4002, '发布角色需要填写名称和人设。');
  if (isGuestUser(req.userId)) return fail(res, 403, 4030, '游客不能使用此功能，请先注册登录。');
  const userProfile = userProfiles.get(req.userId) || { nickname: '体验用户' };
  const item = publishCommunityRole({
    name,
    gender,
    description,
    prompt,
    avatar,
    coverImage,
    orientation,
    tags,
    backgroundStory,
    isPublic: isPublic !== false,
    ownerId: req.userId,
    uploaderNickname: userProfile.nickname || '匿名用户'
  });
  saveData();
  ok(res, item, '人设已保存');
});

app.put('/api/community/roles/:id', (req, res) => {
  const roleId = req.params.id;
  const role = communityRoles.find((r) => r.id === roleId && r.ownerId === req.userId);
  if (!role) return fail(res, 404, 4041, '人设不存在或无权限修改');
  const { name, gender, description, prompt, avatar, coverImage, orientation, tags, backgroundStory, isPublic } = req.body || {};
  if (name !== undefined) role.name = String(name).slice(0, 40);
  if (gender !== undefined) role.gender = String(gender).slice(0, 20);
  if (description !== undefined) role.description = String(description);
  if (prompt !== undefined) role.prompt = String(prompt);
  if (avatar !== undefined) role.avatar = String(avatar).slice(0, 2000);
  if (coverImage !== undefined) role.coverImage = String(coverImage).slice(0, 500000);
  if (orientation !== undefined) role.orientation = String(orientation).slice(0, 10);
  if (Array.isArray(tags)) role.tags = tags.slice(0, 8).map((t) => String(t).slice(0, 12));
  if (backgroundStory !== undefined) role.backgroundStory = String(backgroundStory);
  if (isPublic !== undefined) role.isPublic = isPublic !== false;
  saveData();
  ok(res, role, '人设已更新');
});

app.delete('/api/community/roles/:id', (req, res) => {
  const roleId = req.params.id;
  const index = communityRoles.findIndex((r) => r.id === roleId && r.ownerId === req.userId);
  if (index === -1) return fail(res, 404, 4041, '人设不存在或无权限删除');
  communityRoles.splice(index, 1);
  saveData();
  ok(res, { deleted: true }, '人设已删除');
});

app.post('/api/chat', async (req, res) => {
  const { roleId, roleName, rolePrompt, messages, sourceMessageIds, chatMode, temperature, offlineMinLen, offlineMaxLen } = req.body || {};
  const normalizedMessages = Array.isArray(messages) ? messages.slice(-16) : [];
  const lastUserMessage = [...normalizedMessages].reverse().find((item) => item.role === 'user')?.content || '';
  const activeRoleId = String(roleId || roleName || 'default-role').slice(0, 80);
  if (!lastUserMessage.trim()) return fail(res, 400, 4003, '消息内容不能为空。');

  const user = getUser(req.userId);
  if (isGuestUser(req.userId)) return fail(res, 403, 4030, '游客不能使用此功能，请先注册登录。');
  const actualCost = applyVipDiscount(req.userId, (chatMode === 'offline') ? config.offlineChatBeansCost : config.chatBeansCost);
  if (user.beans < actualCost) return fail(res, 402, 4021, '米粒余额不足，请先充值后再继续聊天。', { beans: user.beans });

  user.beans -= actualCost;
  stats.totalBeansConsumed += actualCost;
  transactions.push({ id: randomUUID(), userId: user.id, type: 'consume', beans: -actualCost, roleName, summary: String(lastUserMessage).slice(0, 60), createdAt: new Date().toISOString() });
  /* 人设创作者分成：消耗米粒的10%奖励给上传者 */
  rewardRoleCreator(activeRoleId, roleName, req.userId, actualCost);
  await saveDataSync();

  /* 读取用户人设及人设关系，注入到 system message */
  const userProfile = userProfiles.get(req.userId) || { nickname: '体验用户', bio: '', relations: '' };
  var personaBlock = '';
  if (userProfile.bio && userProfile.bio.trim()) {
    personaBlock = '\n\n【用户人设】\n用户昵称：' + (userProfile.nickname || '体验用户') + '\n用户人设：' + userProfile.bio;
  }
  /* 注入人设关系，让AI理解角色之间的关系设定 */
  if (userProfile.relations && userProfile.relations.trim()) {
    personaBlock += '\n【人设关系】\n' + userProfile.relations;
  }

  res.setHeader('Content-Type', 'text/event-stream; charset=utf-8');
  res.setHeader('Cache-Control', 'no-cache, no-transform');
  res.setHeader('Connection', 'keep-alive');
  writeSse(res, 'charged', { beans: user.beans, cost: actualCost });

  try {
    if (!config.upstreamKey || config.upstreamKey.includes('请填写')) {
      const memoryNote = buildMemoryPrompt(user.id, activeRoleId);
      const reply = `我是${roleName || 'Mochi-phone 角色'}。我已经收到你的消息：“${lastUserMessage}”。${memoryNote ? '\\n\\n我也会参考我们已有的记忆继续陪你。' : ''}\n\n当前网站后端已运行，但还没有读取到 UPSTREAM_API_KEY，所以先返回演示回复。`;
      await streamText(res, reply);
      /* Auto memory extraction disabled - manual mode */
      stats.totalChatCount += 1;
      saveData();
writeSse(res, 'done', { beans: user.beans });
      return res.end();
    }

    /* 动态平衡：线上需要更多token（800-1000字输出），线下小说叙述较短 */
    const dynamicMaxTokens = chatMode === 'offline' ? 1800 : 2200;
    const dynamicTimeoutMs = chatMode === 'offline' ? 50000 : 45000;
    const upstreamAbortController = new AbortController();
    const upstreamTimeout = setTimeout(() => upstreamAbortController.abort(), dynamicTimeoutMs);
    let upstreamResponse = await fetch(`${config.upstreamBase}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.upstreamKey}` },
      signal: upstreamAbortController.signal,
      body: JSON.stringify({
        model: config.upstreamModel,
        stream: true,
        max_tokens: dynamicMaxTokens,
        temperature: temperature != null ? temperature : 0.85,
        messages: [
          { role: 'system', content: `${rolePrompt || `你正在扮演${roleName || 'AI角色'}，请保持角色一致。`}${personaBlock}${buildMemoryPrompt(user.id, activeRoleId)}${HUMAN_LIKE_PROMPT}

` + (chatMode === 'offline' ? `
【Miya 聊天引擎·线下模式规则·必读】
允许第三人称小说式描写，不用星号动作和表情包，用文字描写表情动作。
1、每轮输出：<thinking> → 正文（一段流畅小说叙述，含场景动作心理对话）→ <miyavoice>
2、对话用引号括起，不要分多条不要用换行分割，正文约${offlineMinLen || 100}-${offlineMaxLen || 300}字
3、可描写面对面互动（拥抱拉手对视等），末尾必须完整输出<miyavoice>，禁止编造用户经历
` : `
【Miya 聊天引擎·线上模式规则·必读】
0、禁止星号*动作*格式，动作神态融入文字，像真人发微信
1、每轮输出三段：<thinking> → 正文（2-5条消息每条独占一行像真人连发微信）→ <miyavoice>；禁止一大坨无换行
2、<thinking>中消化角色设定并落实，正文禁止频繁重复相同话题/描写/句式/同质化撒娇，禁止相同句子出现两次
3、末尾必须完整输出<miyavoice>禁止省略截断，禁止编造用户经历/回忆/偏好，须通读上下文按时间顺序衔接
`) + `

【思维链】
<thinking>内写思考过程：分析用户消息含义和情绪→回顾记忆上下文→决定角色反应和回复方向→考虑人设和当前关系阶段。用户看不到thinking。

` + (chatMode === 'offline' ? `
【心声格式】
每轮末尾输出：
<miyavoice>
心情：<角色当前情绪>
好感：<+1/不变/-1>
想法：<内心真实想法>
小动作：<当前小动作>
</miyavoice>
必须完整输出不可省略。
` : `
【线上格式规则】
1.每次2-5条消息每条独占一行，日常8-25字，情绪激烈/重要时20-50字
2.只用纯文字和表情包，禁主动发图片红包转账语音旁白（除非用户要求），禁描写面对面互动
3.格式：纯文本直接输出 / 表情包-名称（如：表情包-扭捏）

【<miyavoice>格式】
每轮末尾输出：
<miyavoice>
心情：<情绪>
好感：<+1/不变/-1>
想法：<内心想法>
小动作：<当前小动作>
</miyavoice>
必须完整输出。可用表情包：扭捏、送你花、得意、萌物、帅、什么事、亲亲、心都给你啊、kiss、在吗、顺毛、饿、那很坏了、晚安、那咋了、呸、别看扁我、求收留、玻璃心、哈哈哈、靠近、硬撑、思考、停停停、麻了、宝想要、宝得到、想你、谄媚、心虚、来啦、陪我、心碎、夸奖、痛心、感动、知道了、耳聋、没关系、求善待、好痛、害羞、委屈、哭、好想你、发呆、行
禁止主动发图片、红包、转账、语音等。
`) },
          ...normalizedMessages.map((item) => {
            const raw = String(item.content || '');
            // 检测图片消息：图片-data:image/...| 或 图片-URL|
            if (raw.startsWith('图片-')) {
              const pipeIdx = raw.indexOf('|');
              const imgPart = pipeIdx >= 0 ? raw.substring(3, pipeIdx) : raw.substring(3);
              const textPart = pipeIdx >= 0 ? raw.substring(pipeIdx + 1).trim() : '';
              const role = item.role === 'assistant' ? 'assistant' : 'user';
              // 验证图片数据有效性
              if (imgPart.startsWith('data:image/')) {
                // base64 data URL — 转为 OpenAI 多模态格式，detail:low 大幅降低 token 消耗
                const contentArr = [{ type: 'image_url', image_url: { url: imgPart, detail: 'low' } }];
                if (textPart) contentArr.push({ type: 'text', text: textPart });
                return { role, content: contentArr };
              }
              if (/^https?:\/\//.test(imgPart)) {
                // 纯 HTTP URL 图片
                const contentArr = [{ type: 'image_url', image_url: { url: imgPart, detail: 'low' } }];
                if (textPart) contentArr.push({ type: 'text', text: textPart });
                return { role, content: contentArr };
              }
              // 无法识别的图片格式，回退为纯文本描述
              return { role, content: '[图片] ' + (textPart || '') };
            }
            return { role: item.role === 'assistant' ? 'assistant' : 'user', content: raw };
          })
        ]
      })
    }).finally(() => clearTimeout(upstreamTimeout));

    if (!upstreamResponse.ok || !upstreamResponse.body) {
      /* Try to read error body for better context */
      let upstreamErrorMsg = '';
      try {
        const errBody = await upstreamResponse.text();
        const errJson = JSON.parse(errBody);
        upstreamErrorMsg = errJson?.error?.message || errJson?.message || '';
        console.error('[Chat] Upstream error body:', upstreamErrorMsg.slice(0, 200));
      } catch {}
      /* 429 rate limit or quota - return friendly Chinese message */
      if (upstreamResponse.status === 429) {
        throw new Error('AI服务繁忙，请稍后重试。');
      }
      /* 401/403 auth errors - API key issue */
      if (upstreamResponse.status === 401 || upstreamResponse.status === 403) {
        throw new Error('AI服务暂时不可用，请联系管理员。');
      }
      // 5xx错误或连接失败时，尝试一次快速重试
      if (upstreamResponse.status >= 500 || upstreamResponse.status === 0) {
        console.log('[Retry] upstream API returned ' + upstreamResponse.status + ', retrying once...');
        clearTimeout(upstreamTimeout);
        const retryResponse = await fetch(`${config.upstreamBase}/chat/completions`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.upstreamKey}` },
          signal: AbortSignal.timeout(dynamicTimeoutMs),
          body: JSON.stringify({
            model: config.upstreamModel,
            stream: true,
            max_tokens: dynamicMaxTokens,
            temperature: temperature != null ? temperature : 0.85,
            messages: [
              { role: 'system', content: `${rolePrompt || `你正在扮演${roleName || 'AI角色'}，请保持角色一致。`}${personaBlock}${buildMemoryPrompt(user.id, activeRoleId)}${HUMAN_LIKE_PROMPT}` },
              ...normalizedMessages.map((item) => {
                const raw = String(item.content || '');
                if (raw.startsWith('图片-')) {
                  const pipeIdx = raw.indexOf('|');
                  const imgPart = pipeIdx >= 0 ? raw.substring(3, pipeIdx) : raw.substring(3);
                  const textPart = pipeIdx >= 0 ? raw.substring(pipeIdx + 1).trim() : '';
                  const role = item.role === 'assistant' ? 'assistant' : 'user';
                  if (imgPart.startsWith('data:image/') || /^https?:\/\//.test(imgPart)) {
                    const contentArr = [{ type: 'image_url', image_url: { url: imgPart, detail: 'low' } }];
                    if (textPart) contentArr.push({ type: 'text', text: textPart });
                    return { role, content: contentArr };
                  }
                  return { role, content: '[图片] ' + (textPart || '') };
                }
                return { role: item.role === 'assistant' ? 'assistant' : 'user', content: raw };
              })
            ]
          })
        });
        if (retryResponse.ok && retryResponse.body) {
          upstreamResponse = retryResponse;
        } else {
          throw new Error('AI服务暂时不可用，请稍后重试。');
        }
      } else {
        throw new Error('AI服务暂时不可用，请稍后重试。');
      }
    }
    const upstreamContentType = upstreamResponse.headers.get('content-type') || '';
    if (upstreamContentType.includes('application/json')) {
      const data = await upstreamResponse.json();
      const replyText = String(data.choices?.[0]?.message?.content || data.choices?.[0]?.delta?.content || '').trim();
      if (!replyText) {
        refundChatBeans(user, roleName, 'AI 空回复，自动退回本次聊天米粒', actualCost);
        writeSse(res, 'error', {
          message: 'AI 这次没有返回内容，已自动退回本次扣除的米粒，请再试一次。',
          beans: user.beans
        });
        return res.end();
      }
      await streamText(res, replyText);
      stats.totalChatCount += 1;
      saveData();
writeSse(res, 'done', { beans: user.beans });
      res.end();
      console.log('[Chat] Non-stream upstream completed. Role: ' + activeRoleId);
      return;
    }

    const reader = upstreamResponse.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    let replyText = '';

    const handlePayload = (payload) => {
      if (!payload || payload === '[DONE]') return;
      try {
        const json = JSON.parse(payload);
        /* Detect upstream API error in stream (e.g. "AI usage limit reached") */
        if (json.error) {
          const errMsg = String(json.error.message || json.error.type || '');
          console.error('[Chat] Upstream stream error:', errMsg);
          throw new Error('upstream_stream_error:' + errMsg);
        }
        const content = json.choices?.[0]?.delta?.content || json.choices?.[0]?.message?.content || '';
        if (content) {
          /* Filter common English error messages that upstream may return as content */
          const lowerContent = content.toLowerCase();
          if (/^(ai usage limit|rate limit|quota exceeded|insufficient|unauthorized|invalid api key|access denied|service unavailable|internal server error|too many requests)/i.test(content.trim())) {
            console.error('[Chat] Filtered English error content:', content.slice(0, 100));
            throw new Error('upstream_content_error:' + content.slice(0, 200));
          }
          replyText += content;
          writeSse(res, 'delta', { content });
        }
      } catch (parseErr) {
        /* Re-throw upstream errors so outer catch can handle them */
        if (parseErr.message && parseErr.message.startsWith('upstream_')) throw parseErr;
      }
    };

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      const parts = buffer.split('\n\n');
      buffer = parts.pop() || '';
      for (const part of parts) {
        const dataLines = part.split('\n').filter((line) => line.startsWith('data:'));
        for (const line of dataLines) {
          handlePayload(line.replace(/^data:\s*/, '').trim());
        }
      }
    }
    buffer += decoder.decode();

    if (buffer.trim()) {
      const dataLines = buffer.split('\n').filter((line) => line.startsWith('data:'));
      for (const line of dataLines) {
        handlePayload(line.replace(/^data:\s*/, '').trim());
      }
    }

    if (!replyText.trim()) {
      console.log('[Retry] Empty response detected, auto-retrying with simplified prompt...');
      try {
        const emptyRetryResp = await fetch(`${config.upstreamBase}/chat/completions`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.upstreamKey}` },
          signal: AbortSignal.timeout(dynamicTimeoutMs),
          body: JSON.stringify({
            model: config.upstreamModel,
            stream: true,
            max_tokens: dynamicMaxTokens,
            temperature: temperature != null ? temperature : 0.85,
            messages: [
              { role: 'system', content: `${rolePrompt || `你正在扮演${roleName || 'AI角色'}，请保持角色一致。`}${personaBlock}${buildMemoryPrompt(user.id, activeRoleId)}${HUMAN_LIKE_PROMPT}` },
              ...normalizedMessages.map((item) => {
                const raw = String(item.content || '');
                if (raw.startsWith('图片-')) {
                  const pipeIdx = raw.indexOf('|');
                  const imgPart = pipeIdx >= 0 ? raw.substring(3, pipeIdx) : raw.substring(3);
                  const textPart = pipeIdx >= 0 ? raw.substring(pipeIdx + 1).trim() : '';
                  const role = item.role === 'assistant' ? 'assistant' : 'user';
                  if (imgPart.startsWith('data:image/') || /^https?:\/\//.test(imgPart)) {
                    const contentArr = [{ type: 'image_url', image_url: { url: imgPart, detail: 'low' } }];
                    if (textPart) contentArr.push({ type: 'text', text: textPart });
                    return { role, content: contentArr };
                  }
                  return { role, content: '[图片] ' + (textPart || '') };
                }
                return { role: item.role === 'assistant' ? 'assistant' : 'user', content: raw };
              })
            ]
          })
        });
        if (emptyRetryResp.ok && emptyRetryResp.body) {
          const erReader = emptyRetryResp.body.getReader();
          const erDecoder = new TextDecoder();
          let erBuffer = '';
          while (true) {
            const { done, value } = await erReader.read();
            if (done) break;
            erBuffer += erDecoder.decode(value, { stream: true });
            const parts = erBuffer.split('\n\n');
            erBuffer = parts.pop() || '';
            for (const part of parts) {
              const dataLines = part.split('\n').filter((line) => line.startsWith('data:'));
              for (const line of dataLines) {
                const payload = line.replace(/^data:\s*/, '').trim();
                if (!payload || payload === '[DONE]') continue;
                try {
                  const json = JSON.parse(payload);
                  const c = json.choices?.[0]?.delta?.content || json.choices?.[0]?.message?.content || '';
                  if (c) { replyText += c; writeSse(res, 'delta', { content: c }); }
                } catch {}
              }
            }
          }
          erBuffer += erDecoder.decode();
          if (erBuffer.trim()) {
            const dataLines = erBuffer.split('\n').filter((line) => line.startsWith('data:'));
            for (const line of dataLines) {
              const payload = line.replace(/^data:\s*/, '').trim();
              if (!payload || payload === '[DONE]') continue;
              try {
                const json = JSON.parse(payload);
                const c = json.choices?.[0]?.delta?.content || json.choices?.[0]?.message?.content || '';
                if (c) { replyText += c; writeSse(res, 'delta', { content: c }); }
              } catch {}
            }
          }
          console.log('[Retry] Empty retry completed, replyText length = ' + replyText.length);
        }
      } catch (retryErr) {
        console.error('[Retry] Empty response retry failed:', retryErr.message);
      }
      if (!replyText.trim()) {
        refundChatBeans(user, roleName, 'AI 空回复，自动退回本次聊天米粒', actualCost);
        writeSse(res, 'error', {
          message: 'AI 这次没有返回内容，已自动退回本次扣除的米粒，请再试一次。',
          beans: user.beans
        });
        return res.end();
      }
    }

    /* Close connection immediately - memory extraction is now manual */
    stats.totalChatCount += 1;
    saveData();
writeSse(res, 'done', { beans: user.beans });
    res.end();
    /* Automatic memory extraction disabled - users now manually summarize memories from the memory page */
    console.log('[Memory] Auto-extraction disabled (manual mode). Role: ' + activeRoleId);
  } catch (error) {
    refundChatBeans(user, roleName, 'AI 回复失败，自动退回本次聊天米粒', actualCost);
    /* Translate upstream errors to user-friendly Chinese messages */
    let userMessage = 'AI 回复失败，已自动返还本次扣除的米粒。';
    if (error.message && error.message.startsWith('upstream_stream_error:')) {
      const rawErr = error.message.replace('upstream_stream_error:', '');
      userMessage = 'AI服务异常，已自动返还米粒。请稍后重试。';
      console.error('[Chat] Upstream stream error:', rawErr);
    } else if (error.message && error.message.startsWith('upstream_content_error:')) {
      userMessage = 'AI服务暂时不可用，已自动返还米粒。请稍后重试。';
      console.error('[Chat] Filtered error content:', error.message.replace('upstream_content_error:', ''));
    } else if (error.message && error.message.includes('AI服务繁忙')) {
      userMessage = 'AI当前使用人数较多，已自动返还米粒。请稍后重试。';
    } else if (error.message && error.message.includes('AI服务暂时不可用')) {
      userMessage = error.message + '已自动返还米粒。';
    }
    writeSse(res, 'error', { message: userMessage, beans: user.beans });
    res.end();
  }
});

/* === APP iframe chat endpoint - returns JSON (not SSE) ===
 * 专门给 APP iframe 调用，返回完整 JSON 一次性响应。
 * 不使用流式传输，等待 AI 完整回复后返回。
 */
app.post('/api/app/chat', async (req, res) => {
  const { roleId, roleName, rolePrompt, messages, temperature } = req.body || {};
  const normalizedMessages = Array.isArray(messages) ? messages.slice(-20) : [];
  const lastUserMessage = [...normalizedMessages].reverse().find((item) => item.role === 'user')?.content || '';
  const activeRoleId = String(roleId || roleName || 'default-role').slice(0, 80);
  if (!lastUserMessage.trim()) return fail(res, 400, 4003, '消息内容不能为空。');

  const user = getUser(req.userId);
  if (isGuestUser(req.userId)) return fail(res, 403, 4030, '游客不能使用此功能，请先注册登录。');
  const actualCost = applyVipDiscount(req.userId, config.chatBeansCost);
  if (user.beans < actualCost) return fail(res, 402, 4021, '米粒余额不足，请先充值后再继续聊天。', { beans: user.beans });

  user.beans -= actualCost;
  stats.totalBeansConsumed += actualCost;
  transactions.push({ id: randomUUID(), userId: user.id, type: 'consume', beans: -actualCost, roleName, summary: String(lastUserMessage).slice(0, 60), createdAt: new Date().toISOString() });
  /* 人设创作者分成：消耗米粒的10%奖励给上传者 */
  rewardRoleCreator(activeRoleId, roleName, req.userId, actualCost);
  await saveDataSync();

  /* 读取用户人设 */
  const userProfile = userProfiles.get(req.userId) || { nickname: '体验用户', bio: '', relations: '' };
  var personaBlock = '';
  if (userProfile.bio && userProfile.bio.trim()) {
    personaBlock = '\n\n【用户人设】\n用户昵称：' + (userProfile.nickname || '体验用户') + '\n用户人设：' + userProfile.bio;
  }
  if (userProfile.relations && userProfile.relations.trim()) {
    personaBlock += '\n【人设关系】\n' + userProfile.relations;
  }

  try {
    if (!config.upstreamKey || config.upstreamKey.includes('请填写')) {
      const memoryNote = buildMemoryPrompt(user.id, activeRoleId);
      const reply = `我是${roleName || 'Mochi-phone 角色'}。我已经收到你的消息："${lastUserMessage}"。${memoryNote ? '\n\n我也会参考我们已有的记忆继续陪你。' : ''}\n\n当前网站后端已运行，但还没有读取到 UPSTREAM_API_KEY，所以先返回演示回复。`;
      stats.totalChatCount += 1;
      saveData();
return res.json({ code: 0, data: { content: reply, beans: user.beans } });
    }

    /* 非流式调用上游 API，等待完整回复 */
    const upstreamAbortController = new AbortController();
    const upstreamTimeout = setTimeout(() => upstreamAbortController.abort(), 45000);
    let upstreamResponse = await fetch(`${config.upstreamBase}/chat/completions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${config.upstreamKey}` },
      signal: upstreamAbortController.signal,
      body: JSON.stringify({
        model: config.upstreamModel,
        stream: false,
        max_tokens: 2200,
        temperature: temperature != null ? temperature : 0.85,
        messages: [
          { role: 'system', content: `${rolePrompt || `你正在扮演${roleName || 'AI角色'}，请保持角色一致。`}${personaBlock}${buildMemoryPrompt(user.id, activeRoleId)}

你是一个友好的AI助手，请用自然口语风格回复，保持角色设定。` },
          ...normalizedMessages.map((item) => {
            const raw = String(item.content || '');
            if (raw.startsWith('图片-')) {
              const pipeIdx = raw.indexOf('|');
              const imgPart = pipeIdx >= 0 ? raw.substring(3, pipeIdx) : raw.substring(3);
              const textPart = pipeIdx >= 0 ? raw.substring(pipeIdx + 1).trim() : '';
              const role = item.role === 'assistant' ? 'assistant' : 'user';
              if (imgPart.startsWith('data:image/') || /^https?:\/\//.test(imgPart)) {
                const contentArr = [{ type: 'image_url', image_url: { url: imgPart, detail: 'low' } }];
                if (textPart) contentArr.push({ type: 'text', text: textPart });
                return { role, content: contentArr };
              }
              return { role, content: '[图片] ' + (textPart || '') };
            }
            return { role: item.role === 'assistant' ? 'assistant' : 'user', content: raw };
          })
        ]
      })
    }).finally(() => clearTimeout(upstreamTimeout));

    if (!upstreamResponse.ok) {
      let upstreamErrorMsg = '';
      try {
        const errBody = await upstreamResponse.text();
        const errJson = JSON.parse(errBody);
        upstreamErrorMsg = errJson?.error?.message || errJson?.message || '';
        console.error('[AppChat] Upstream error:', upstreamErrorMsg.slice(0, 200));
      } catch {}
      if (upstreamResponse.status === 429) {
        throw new Error('AI服务繁忙，请稍后重试。');
      }
      if (upstreamResponse.status === 401 || upstreamResponse.status === 403) {
        throw new Error('AI服务暂时不可用，请联系管理员。');
      }
      throw new Error('AI服务暂时不可用，请稍后重试。');
    }

    const data = await upstreamResponse.json();
    const replyText = data.choices?.[0]?.message?.content || data.choices?.[0]?.delta?.content || '';

    if (!replyText.trim()) {
      refundChatBeans(user, roleName, 'AI 空回复，自动退回本次聊天米粒', actualCost);
      return res.json({ code: 500, message: 'AI 这次没有返回内容，已自动退回米粒，请再试一次。', data: { beans: user.beans } });
    }

    /* Filter common English error messages */
    const lowerReply = replyText.toLowerCase();
    if (/^(ai usage limit|rate limit|quota exceeded|insufficient|unauthorized|invalid api key|access denied|service unavailable|internal server error|too many requests)/i.test(replyText.trim())) {
      console.error('[AppChat] Filtered English error content:', replyText.slice(0, 200));
      refundChatBeans(user, roleName, 'AI 返回异常，自动退回米粒', actualCost);
      return res.json({ code: 500, message: 'AI服务暂时不可用，已自动返还米粒。请稍后重试。', data: { beans: user.beans } });
    }

    stats.totalChatCount += 1;
    saveData();
res.json({ code: 0, data: { content: replyText, beans: user.beans } });
  } catch (error) {
    refundChatBeans(user, roleName, 'AI 回复失败，自动退回本次聊天米粒', actualCost);
    let userMessage = 'AI 回复失败，已自动返还本次扣除的米粒。';
    if (error.message && error.message.includes('AI服务繁忙')) {
      userMessage = 'AI当前使用人数较多，已自动返还米粒。请稍后重试。';
    } else if (error.message && error.message.includes('AI服务暂时不可用')) {
      userMessage = error.message + '已自动返还米粒。';
    } else if (error.name === 'AbortError') {
      userMessage = 'AI回复超时，已自动返还米粒。请稍后重试。';
    }
    console.error('[AppChat] Error:', error.message);
    res.json({ code: 500, message: userMessage, data: { beans: user.beans } });
  }
});


