// ------------------------------------------------------------
// 辅助函数
// ------------------------------------------------------------
// ------------------------------------------------------------

function buildSystemPrompt(appConfig, role, userPersona) {
  var roleName = (role && role.name) ? role.name : '角色';
  var rolePrompt = (role && role.prompt) ? role.prompt : '';
  var userName = '普通用户';
  if (userPersona) {
    if (typeof userPersona === 'string') {
      userName = userPersona;
    } else if (userPersona.name) {
      userName = userPersona.name;
    }
  }
  /* 角色身份锁：在系统提示词最前面写入角色名和人设，防止AI混淆角色 */
  var characterLock = '【角色身份锁·最高优先级】\n';
  characterLock += '你现在正在深度模拟角色"' + roleName + '"的手机。\n';
  characterLock += '你只能生成' + roleName + '的手机内容，绝对不能混入任何其他角色的人设、记忆或社交关系。\n';
  characterLock += '【角色核心人设】: ' + (rolePrompt || '无特殊人设') + '\n\n';
  var prompt = appConfig.systemPrompt || '';
  prompt = prompt.replace(/\{角色名\}/g, roleName);
  prompt = prompt.replace(/\{用户名\}/g, userName);
  return characterLock + prompt;
}

// 构建用户提示词
function buildUserPrompt(body, appConfig) {
  const { role, userPersona, relationship, recentChatHistory, memorySummary } = body;
  const roleName = role?.name || '未知角色';
  /* 截断 rolePrompt，防止超长人设导致 prompt 过大触发 API 400 */
  const rolePrompt = role?.prompt || '';
  /* 移除 avatar：base64 头像数据可达 20KB+，会撑爆 API 请求 */
  const userP = userPersona || '普通用户';
  const rel = relationship || '朋友';
  const currentTime = getCurrentTimeString();
  const appName = appConfig.name;

  let chatSection = '';
  if (recentChatHistory && recentChatHistory.trim()) {
    /* 截断聊天记录，防止过长 */
    const trimmedChat = recentChatHistory.length > 3000 ? recentChatHistory.substring(0, 3000) + '...' : recentChatHistory;
    chatSection = `
=== 核心记忆库（最近聊天记录） ===
--- 聊天记录开始 ---
${trimmedChat}
--- 聊天记录结束 ---
`;
  }

  let memorySection = '';
  if (memorySummary && memorySummary.trim()) {
    /* 截断记忆摘要 */
    const trimmedMem = memorySummary.length > 1000 ? memorySummary.substring(0, 1000) + '...' : memorySummary;
    memorySection = `
=== 历史记忆摘要 ===
${trimmedMem}
`;
  }

  return `请为以下角色生成手机【${appName}】的内容。

=== 角色信息 ===
角色名：${roleName}
角色人设：${rolePrompt}

=== 用户信息 ===
用户人设：${userP}
与角色的关系：${rel}
${chatSection}${memorySection}
=== 生成要求 ===
App类型：${appName}（appId: ${body.appId}）
内容数量：${appConfig.count}
当前时间：${currentTime}

【活人感核心法则（最高优先级）】
1. 记忆锚定：所有内容必须融合上述角色信息、聊天记录和记忆摘要中的情报。内容要呼应最近发生的事，不能脱离上下文凭空生成。
2. 虚实结合：可以补充日常琐事（虚构同事、邻居、小事件），但绝不能与聊天记录和记忆中的事实矛盾。严禁凭空创造改变角色人生轨迹的重大事件。
3. 时间一致：所有时间戳必须与当前时间 ${currentTime} 保持逻辑一致，不得出现时间悖论。
4. 每次全新：本次生成的内容必须是全新的，不得重复之前可能生成过的内容。
5. 语言要求：所有文字（包括网友昵称）必须使用简体中文。
6. 人设自洽：内容细节必须匹配角色人设——职业决定消费水平，性格决定行为模式，近期状态决定情绪基调。
7. 行为链交叉验证：同一个角色在不同App中产生的数据必须在时间线和事件上能互相印证。例如：微信聊天提到"中午和同事吃了火锅"，那么相册中应有火锅照片，运动健康App的步数在午间应偏高，支付宝应有火锅店消费记录。
8. 矛盾心理还原：真实的人内心是矛盾的。角色在聊天中对某人说"没事"，但搜索记录里可能有"如何掩饰情绪"。让角色的内心冲突通过不同App的数据自然流露。
9. 沉默信息：有时候"没有"本身就是信息。适当制造信息缺失和留白，让用户自己去发现和解读。
10. 时间颗粒度真实化：真实手机数据的时间分布是不均匀的。要模拟真实的作息节奏和信息密度波动。
11. 数字痕迹叠加：同一天使用不同App时，会留下相互关联的数字痕迹。让不同App数据形成立体的生活切面。
12. 未完成状态保留：真实手机里充满未完成的事物——打了字没发的草稿、看了一半的视频、加了购物车没付款的商品。
13. 社交关系网一致性：角色在不同App中出现的社交对象应保持一致，形成连贯的社交网络。
14. 情绪暗流渗透：角色的情绪状态会无意识地渗透到各个App的使用中。

请严格遵循系统提示词中规定的 JSON 字段名、数量要求和格式要求。根据角色的人设和性格，生成真实、自然、有趣的${appName}内容。

【重要】请严格按照系统提示词中定义的字段名和结构输出 JSON。不要使用自己的字段名，必须使用系统提示词中指定的字段名。只输出JSON，不要包含任何其他文字、不要使用 markdown 代码块。`;
}

// ------------------------------------------------------------
// API 端点
// ------------------------------------------------------------

// 4.1 GET /api/phone-check/:roleId - 获取角色的所有手机数据
app.get('/api/phone-check/:roleId', async (req, res) => {
  try {
    const userId = req.userId;
    const { roleId } = req.params;

    if (!userId) {
      return res.status(401).json({ code: 401, message: '未授权，请登录', error: '未授权' });
    }

    const key = `phone_check:${userId}:${roleId}`;
    const data = await dbGet(key);

    res.json({
      code: 0,
      message: 'success',
      success: true,
      data: data || {}
    });
  } catch (err) {
    console.error('[phone-check] 获取数据失败:', err);
    res.status(200).json({ code: 500, message: '获取数据失败: ' + err.message, error: '获取数据失败', detail: err.message });
  }
});

// 4.2 POST /api/phone-check/:roleId/:appId/generate - AI 生成指定 App 的数据
const PHONE_CHECK_BEAN_COST = 2; // 查手机每次生成消耗2米粒
app.post('/api/phone-check/:roleId/:appId/generate', async (req, res) => {
  let refundPcBeans = null;
  try {
    const userId = req.userId;
    const { roleId, appId } = req.params;

    if (!userId) {
      return res.status(401).json({ code: 401, message: '未授权，请登录', error: '未授权' });
    }

    // 校验 appId 是否有效
    const appConfig = PHONE_CHECK_APPS[appId];
    if (!appConfig) {
      return res.status(400).json({ code: 400, message: '无效的 appId', error: '无效的 appId', validApps: Object.keys(PHONE_CHECK_APPS) });
    }

    // 校验请求体
    const { role, userPersona, relationship } = req.body;
    if (!role || !role.name) {
      return res.status(400).json({ code: 400, message: '请求体缺少 role.name 字段', error: '请求体缺少 role.name 字段' });
    }

    // 扣除米粒
    const user = getUser(userId);
    if (isGuestUser(req.userId)) return fail(res, 403, 4030, '游客不能使用此功能，请先注册登录。');
    const pcCost = PHONE_CHECK_BEAN_COST;
    console.log(`[phone-check] 米粒检查: userId=${userId}, beans=${user.beans}, cost=${pcCost}`);
    if (user.beans < pcCost) {
      console.warn(`[phone-check] 米粒不足: userId=${userId}, beans=${user.beans}, need=${pcCost}`);
      return res.status(200).json({ code: 402, message: '米粒不足，查手机需要' + pcCost + '颗米粒（当前余额：' + user.beans + '）', error: '米粒不足', beans: user.beans });
    }
    user.beans -= pcCost;
    stats.totalBeansConsumed += pcCost;
    transactions.push({ id: randomUUID(), userId: user.id, type: 'consume', beans: -pcCost, roleName: role.name, summary: '查手机-' + appConfig.name, createdAt: new Date().toISOString() });
    await saveDataSync();
    refundPcBeans = () => { user.beans += pcCost; stats.totalBeansConsumed -= pcCost; saveDataSync().catch(()=>{}); };
    console.log(`[phone-check] 用户 ${userId} 消耗 ${pcCost} 米粒生成 ${appConfig.name}`);

    // === 后台模式：立即返回taskId，异步生成（解决pro模型118秒超时问题） ===
    if (req.body.background) {
      const pcBgTask = createBgTask(userId, 'phone-check', '生成' + appConfig.name);
      ok(res, { background: true, taskId: pcBgTask.id });
      console.log(`[phone-check][bg] 后台任务已创建 taskId=${pcBgTask.id}, appId=${appId}, role=${role.name}`);
      (async () => {
        try {
          const systemPrompt = buildSystemPrompt(appConfig, role, userPersona);
          const userPrompt = buildUserPrompt({ ...req.body, appId }, appConfig);
          console.log(`[phone-check][bg] 开始生成 appId=${appId}, role=${role.name}`);
          const PC_BG_FALLBACK = ['[次-流抗截]gemini-3.1-pro-preview', '[次]gemini-2.5-pro', '[次]gemini-3-flash-preview'];
          const bgPrimary = config.upstreamModel;
          const bgModels = [bgPrimary, ...PC_BG_FALLBACK.filter(m => m !== bgPrimary)];
          let bgResponse = null;
          let bgErrText = '';
          let bgErrStatus = 0;
          for (let _bi = 0; _bi < bgModels.length; _bi++) {
            const _bgModel = bgModels[_bi];
            const _bgAbort = new AbortController();
            const _bgTimeout = setTimeout(() => _bgAbort.abort(), 90000);
            try {
              console.log(`[phone-check][bg] 尝试模型 ${_bi + 1}/${bgModels.length}: ${_bgModel}`);
              bgResponse = await fetch(config.upstreamBase + '/chat/completions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.upstreamKey },
                signal: _bgAbort.signal,
                body: JSON.stringify({ model: _bgModel, temperature: 0.88, max_tokens: 8192, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt }] })
              });
              clearTimeout(_bgTimeout);
              if (bgResponse.ok) { console.log(`[phone-check][bg] 模型 ${_bgModel} 成功`); break; }
              try { bgErrText = await bgResponse.text(); } catch(e) { bgErrText = ''; }
              bgErrStatus = bgResponse.status;
              console.warn(`[phone-check][bg] 模型 ${_bgModel} 返回 HTTP ${bgErrStatus}: ${bgErrText.substring(0, 200)}`);
              bgResponse = null;
            } catch(bgFetchErr) {
              clearTimeout(_bgTimeout);
              console.warn(`[phone-check][bg] 模型 ${_bgModel} 异常: ${bgFetchErr.message}`);
              bgErrText = bgFetchErr.message;
              bgErrStatus = 0;
              bgResponse = null;
            }
          }
          if (!bgResponse) {
            throw new Error(bgErrStatus > 0 ? 'AI服务返回错误(HTTP ' + bgErrStatus + ')，请稍后重试' : 'AI服务请求超时或网络异常，请重试');
          }
          const bgData = await bgResponse.json();
          let bgContent = bgData.choices?.[0]?.message?.content;
          if (!bgContent) throw new Error('AI 返回内容为空，请重试');
          let bgParsed = parseAIJson(bgContent);
          if (!bgParsed) {
            console.warn('[phone-check][bg] 首次JSON解析失败，重试...');
            const _bgRetryAbort = new AbortController();
            const _bgRetryTimeout = setTimeout(() => _bgRetryAbort.abort(), 90000);
            try {
              const _bgRetryResp = await fetch(config.upstreamBase + '/chat/completions', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + config.upstreamKey },
                signal: _bgRetryAbort.signal,
                body: JSON.stringify({ model: bgModels[0], temperature: 0.5, max_tokens: 8192, messages: [{ role: 'system', content: systemPrompt }, { role: 'user', content: userPrompt + '\n\n【重要提醒】上一次回复无法解析为JSON。请只输出纯JSON对象，不要包含任何markdown标记、解释文字或代码块。第一个字符必须是{，最后一个字符必须是}。' }] })
              });
              clearTimeout(_bgRetryTimeout);
              if (_bgRetryResp.ok) {
                const _bgRetryData = await _bgRetryResp.json();
                const _bgRetryContent = _bgRetryData.choices?.[0]?.message?.content;
                if (_bgRetryContent) bgParsed = parseAIJson(_bgRetryContent);
              }
            } catch(_bgRetryErr) { clearTimeout(_bgRetryTimeout); }
            if (!bgParsed) throw new Error('AI 返回内容解析失败，请重试');
          }
          // 保存到DB
          try {
            const _indKey = `phone_check:${userId}:${roleId}:${appId}`;
            await dbSet(_indKey, bgParsed);
            const _aggKey = `phone_check:${userId}:${roleId}`;
            let _aggData = await dbGet(_aggKey);
            if (!_aggData || typeof _aggData !== 'object') _aggData = {};
            _aggData[appId] = { appName: appConfig.name, data: bgParsed, savedAt: getCurrentTimeString() };
            await dbSet(_aggKey, _aggData);
            console.log(`[phone-check][bg] 数据已保存 appId=${appId}`);
          } catch(_saveErr) {
            console.error('[phone-check][bg] 保存失败:', _saveErr.message);
          }
          const _bgUser = getUser(userId);
          console.log(`[phone-check][bg] 生成成功 appId=${appId}`);
          completeBgTask(pcBgTask.id, { appId: appId, appName: appConfig.name, data: bgParsed, beans: _bgUser ? _bgUser.beans : undefined });
        } catch (bgErr) {
          console.error('[phone-check][bg] 生成失败:', bgErr.message);
          if (refundPcBeans) refundPcBeans();
          failBgTask(pcBgTask.id, bgErr.message || '生成失败');
        }
      })();
      return;
    }

    // 构建提示词
    const systemPrompt = buildSystemPrompt(appConfig, role, userPersona);
    const userPrompt = buildUserPrompt({ ...req.body, appId }, appConfig);

    console.log(`[phone-check] 开始生成 appId=${appId}, roleId=${roleId}, role=${role.name}`);

    // 调用上游 AI API（加超时保护 + 模型 fallback 机制）
    const PC_FALLBACK_MODELS = ['[次-流抗截]gemini-3.1-pro-preview', '[次]gemini-2.5-pro', '[次]gemini-3-flash-preview'];
    const primaryModel = config.upstreamModel;
    const modelsToTry = [primaryModel, ...PC_FALLBACK_MODELS.filter(m => m !== primaryModel)];
    let response = null;
    let lastErrText = '';
    let lastErrStatus = 0;
    let modelUsed = '';

    for (let _mi = 0; _mi < modelsToTry.length; _mi++) {
      const _tryModel = modelsToTry[_mi];
      const pcAbortController = new AbortController();
      const pcTimeout = setTimeout(() => pcAbortController.abort(), 60000);
      try {
        console.log(`[phone-check] 尝试模型 ${_mi + 1}/${modelsToTry.length}: ${_tryModel}`);
        response = await fetch(config.upstreamBase + '/chat/completions', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + config.upstreamKey
          },
          signal: pcAbortController.signal,
          body: JSON.stringify({
            model: _tryModel,
            temperature: 0.88,
            max_tokens: 8192,
            messages: [
              { role: 'system', content: systemPrompt },
              { role: 'user', content: userPrompt }
            ]
          })
        });
        clearTimeout(pcTimeout);
        if (response.ok) {
          modelUsed = _tryModel;
          console.log(`[phone-check] 模型 ${_tryModel} 成功`);
          break;
        }
        /* 非 200，记录错误并尝试下一个模型 */
        try { lastErrText = await response.text(); } catch(e) { lastErrText = ''; }
        lastErrStatus = response.status;
        console.warn(`[phone-check] 模型 ${_tryModel} 返回 HTTP ${response.status}: ${lastErrText.substring(0, 200)}`);
        response = null;
        /* 429 限流或 500+ 服务器错误才尝试下一个模型；400 可能是 prompt 问题也试下一个 */
      } catch(fetchErr) {
        clearTimeout(pcTimeout);
        console.warn(`[phone-check] 模型 ${_tryModel} 请求异常: ${fetchErr.message}`);
        lastErrText = fetchErr.message;
        lastErrStatus = 0;
        response = null;
      }
    }

    /* 所有模型都失败 */
    if (!response) {
      console.error('[phone-check] 所有模型均失败，最后错误:', lastErrStatus, lastErrText.substring(0, 300));
      refundPcBeans();
      const errMsg = lastErrStatus > 0
        ? 'AI服务返回错误(HTTP ' + lastErrStatus + ')，请稍后重试'
        : 'AI服务请求超时或网络异常，请重试';
      return res.status(200).json({
        code: 500,
        message: errMsg,
        error: 'AI请求失败',
        status: lastErrStatus,
        detail: lastErrText.substring(0, 500)
      });
    }

    let data;
    try {
      data = await response.json();
    } catch(jsonErr) {
      console.error('[phone-check] AI响应JSON解析失败:', jsonErr.message);
      refundPcBeans();
      return res.status(200).json({
        code: 500,
        message: 'AI服务响应格式异常，请重试',
        error: 'AI响应解析失败',
        detail: jsonErr.message
      });
    }
    let content = data.choices?.[0]?.message?.content;

    if (!content) {
      console.error('[phone-check] AI 返回内容为空');
      refundPcBeans();
      return res.status(200).json({ code: 500, message: 'AI 返回内容为空，请重试', error: 'AI 返回内容为空' });
    }

    // 解析 JSON（容错处理）
    let parsed = parseAIJson(content);

    if (!parsed) {
      console.error('[phone-check] 首次JSON解析失败，启动重试...');
      /* 重试一次：降低temperature，强化JSON输出要求（加超时保护 + 模型fallback） */
      var retryResponse = null;
      for (let _ri = 0; _ri < modelsToTry.length && !retryResponse; _ri++) {
        const _retryModel = modelsToTry[_ri];
        const retryAbort = new AbortController();
        const retryTimeout = setTimeout(() => retryAbort.abort(), 60000);
        try {
          retryResponse = await fetch(config.upstreamBase + '/chat/completions', {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Authorization': 'Bearer ' + config.upstreamKey
            },
            signal: retryAbort.signal,
            body: JSON.stringify({
              model: _retryModel,
              temperature: 0.5,
              max_tokens: 8192,
              messages: [
                { role: 'system', content: systemPrompt },
                { role: 'user', content: userPrompt + '\n\n【重要提醒】上一次回复无法解析为JSON。请只输出纯JSON对象，不要包含任何markdown标记、解释文字或代码块。第一个字符必须是{，最后一个字符必须是}。' }
              ]
            })
          });
          if (!retryResponse.ok) {
            console.warn(`[phone-check] 重试模型 ${_retryModel} 返回 ${retryResponse.status}`);
            retryResponse = null;
          }
        } catch(retryFetchErr) {
          console.warn(`[phone-check] 重试模型 ${_retryModel} 异常: ${retryFetchErr.message}`);
          retryResponse = null;
        }
        clearTimeout(retryTimeout);
      }
      if (retryResponse && retryResponse.ok) {
        try {
          var retryData = await retryResponse.json();
          var retryContent = retryData.choices?.[0]?.message?.content;
          if (retryContent) {
            var retryParsed = parseAIJson(retryContent);
            if (retryParsed) {
              console.log('[phone-check] 重试成功，JSON解析通过');
              /* 用重试结果继续后续流程 */
              parsed = retryParsed;
              content = retryContent;
            }
          }
        } catch(retryJsonErr) {
          console.error('[phone-check] 重试响应解析失败:', retryJsonErr.message);
        }
      }
      /* 如果重试后仍然无法解析，才报错 */
      if (!parsed) {
        console.error('[phone-check] 重试后仍解析失败');
        refundPcBeans();
        return res.status(200).json({
          code: 500,
          message: 'AI 返回内容解析失败，请重试',
          error: 'AI 返回内容解析失败',
          rawContent: content.substring(0, 1000)
        });
      }
    }

    console.log(`[phone-check] 生成成功 appId=${appId}`);

    // 保存生成的数据到服务端
    try {
      const individualKey = `phone_check:${userId}:${roleId}:${appId}`;
      await dbSet(individualKey, parsed);

      const aggregateKey = `phone_check:${userId}:${roleId}`;
      let aggregateData = await dbGet(aggregateKey);
      if (!aggregateData || typeof aggregateData !== 'object') {
        aggregateData = {};
      }
      aggregateData[appId] = {
        appName: appConfig.name,
        data: parsed,
        savedAt: getCurrentTimeString()
      };
      await dbSet(aggregateKey, aggregateData);
      console.log(`[phone-check] 生成数据已自动保存 appId=${appId}`);
    } catch (saveErr) {
      console.error('[phone-check] 生成数据自动保存失败:', saveErr.message);
    }

    const updatedUser = getUser(userId);
    res.json({
      code: 0,
      message: 'success',
      success: true,
      appId: appId,
      appName: appConfig.name,
      data: parsed,
      beans: updatedUser ? updatedUser.beans : undefined
    });
  } catch (err) {
    console.error('[phone-check] 生成失败:', err);
    if (refundPcBeans) refundPcBeans();
    res.status(200).json({ code: 500, message: '生成失败: ' + (err.message || '未知错误'), error: '生成失败', detail: err.message });
  }
});

// 4.3 POST /api/phone-check/:roleId/:appId/save - 保存 App 数据
app.post('/api/phone-check/:roleId/:appId/save', async (req, res) => {
  try {
    const userId = req.userId;
    const { roleId, appId } = req.params;

    if (!userId) {
      return res.status(401).json({ code: 401, message: '未授权，请登录', error: '未授权' });
    }

    // 校验 appId 是否有效
    const appConfig = PHONE_CHECK_APPS[appId];
    if (!appConfig) {
      return res.status(400).json({ code: 400, message: '无效的 appId', error: '无效的 appId', validApps: Object.keys(PHONE_CHECK_APPS) });
    }

    const appData = req.body?.data;
    if (appData === undefined || appData === null) {
      return res.status(400).json({ code: 400, message: '请求体缺少 data 字段', error: '请求体缺少 data 字段' });
    }

    // 保存单个 App 数据
    const individualKey = `phone_check:${userId}:${roleId}:${appId}`;
    await dbSet(individualKey, appData);

    // 更新聚合数据（所有 App 数据汇总）
    const aggregateKey = `phone_check:${userId}:${roleId}`;
    let aggregateData = await dbGet(aggregateKey);
    if (!aggregateData || typeof aggregateData !== 'object') {
      aggregateData = {};
    }
    aggregateData[appId] = {
      appName: appConfig.name,
      data: appData,
      savedAt: getCurrentTimeString()
    };
    await dbSet(aggregateKey, aggregateData);

    console.log(`[phone-check] 保存成功 appId=${appId}, roleId=${roleId}`);

    res.json({
      code: 0,
      message: '保存成功',
      success: true,
      appId: appId,
      appName: appConfig.name
    });
  } catch (err) {
    console.error('[phone-check] 保存失败:', err);
    res.status(200).json({ code: 500, message: '保存失败: ' + err.message, error: '保存失败', detail: err.message });
  }
});

// 4.4 DELETE /api/phone-check/:roleId/:appId - 删除 App 数据
app.delete('/api/phone-check/:roleId/:appId', async (req, res) => {
  try {
    const userId = req.userId;
    const { roleId, appId } = req.params;

    if (!userId) {
      return res.status(401).json({ code: 401, message: '未授权，请登录', error: '未授权' });
    }

    // 删除单个 App 数据
    const individualKey = `phone_check:${userId}:${roleId}:${appId}`;
    await dbSet(individualKey, null);

    // 从聚合数据中移除
    const aggregateKey = `phone_check:${userId}:${roleId}`;
    let aggregateData = await dbGet(aggregateKey);
    if (aggregateData && typeof aggregateData === 'object' && aggregateData[appId]) {
      delete aggregateData[appId];
      await dbSet(aggregateKey, aggregateData);
    }

    console.log(`[phone-check] 删除成功 appId=${appId}, roleId=${roleId}`);

    res.json({
      code: 0,
      message: '删除成功',
      success: true,
      appId: appId
    });
  } catch (err) {
    console.error('[phone-check] 删除失败:', err);
    res.status(200).json({ code: 500, message: '删除失败: ' + err.message, error: '删除失败', detail: err.message });
  }
});

